  }),
  Object.freeze({
    member_type: 'ContractFreezeGoverningSpecificationMember',
    schema_id: 'ContractFreezeGoverningSpecificationMember/V1',
    preparation_state: 'EXTERNAL_INPUT_REQUIRED',
  }),
  Object.freeze({
