        input('BroadRouteContainmentAttestation', '/runtime_route_ids'),
      ]),
    }),
  }),
]);

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function requireDigest(value, label) {
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value)) {
    throw new TypeError(`${label} must be a SHA-256 digest`);
  }
  return value;
}

function executableBindingsFor(configuration) {
  const descriptor = acceptanceDescriptorForContract(configuration.evidence_contract);
  if (descriptor.activation_state !== 'ACTIVE') {
    throw new Error(`${configuration.gate_id} acceptance descriptor is not active`);
  }
  const memberSchemaSet = configuration.member_schema_set;
  const enumeratorConfiguration = {
    evidence_contract: configuration.evidence_contract,
    member_schema_set: memberSchemaSet,
    ordering_rule: 'UTF8_MEMBER_TYPE_THEN_ID',
  };
  const predicates = ACCEPTANCE_PREDICATES[configuration.gate_id];
  const predicateBindings = {};
  for (const claimKey of descriptor.ordered_claim_keys) {
    const predicate = predicates && predicates[claimKey];
    const exactInputs = configuration.claim_inputs?.[claimKey]
      || (
        Array.isArray(configuration.claim_paths[claimKey])
          ? configuration.claim_paths[claimKey]
          : [configuration.claim_paths[claimKey]]
      ).map((jsonPointer) => ({
        member_type: descriptor.evidence_object_type,
        json_pointer: jsonPointer,
      }));
    if (typeof predicate !== 'function') {
      throw new Error(`${configuration.gate_id} has no executable predicate ${claimKey}`);
    }
    if (!Array.isArray(exactInputs) || exactInputs.length === 0) {
      throw new Error(`${configuration.gate_id} has no exact inputs for ${claimKey}`);
    }
    if (exactInputs.some((entry) => (
      !entry
      || typeof entry.member_type !== 'string'
      || entry.member_type.length === 0
      || typeof entry.json_pointer !== 'string'
      || !entry.json_pointer.startsWith('/')
    ))) {
      throw new Error(`${configuration.gate_id} has an invalid exact input for ${claimKey}`);
    }
    const predicateEntryDigest = domainDigest(
      PREDICATE_EXECUTABLE_DOMAIN,
      { gate_id: configuration.gate_id, claim_key: claimKey, source: predicate.toString() },
    );
    predicateBindings[claimKey] = Object.freeze({
      exact_inputs: Object.freeze(exactInputs.map((entry) => Object.freeze({ ...entry }))),
      executable_digest: domainDigest(
        TRANSITIVE_EXECUTABLE_DOMAIN,
        {
          executable_kind: 'PREDICATE',
          entry_executable_digest: predicateEntryDigest,
          transitive_source_closure_digest: ACCEPTANCE_EXECUTABLE_CLOSURE_DIGEST,
        },
      ),
      configuration_digest: domainDigest(
        PREDICATE_CONFIGURATION_DOMAIN,
        {
          gate_id: configuration.gate_id,
          claim_key: claimKey,
          exact_inputs: exactInputs,
        },
      ),
    });
  }
  return Object.freeze({
    member_enumerator: Object.freeze({
      executable_digest: domainDigest(
        TRANSITIVE_EXECUTABLE_DOMAIN,
        {
          executable_kind: 'MEMBER_ENUMERATOR',
          entry_executable_digest: configuration.member_enumerator_executable_digest
            || ENUMERATOR_EXECUTABLE_DIGEST,
          transitive_source_closure_digest: ACCEPTANCE_EXECUTABLE_CLOSURE_DIGEST,
        },
      ),
      configuration_digest: domainDigest(
        ENUMERATOR_CONFIGURATION_DOMAIN,
        enumeratorConfiguration,
      ),
    }),
    predicates: Object.freeze(predicateBindings),
  });
}

function definitionFor(configuration, specificationRoot, executableBindings) {
  const descriptor = acceptanceDescriptorForContract(configuration.evidence_contract);
  const memberSchemaSet = configuration.member_schema_set;
  const definition = {
    schema_version: 'ProgrammeGateAcceptanceDefinition/V1',
    definition_id: '0'.repeat(64),
    definition_digest: '0'.repeat(64),
    evidence_contract: configuration.evidence_contract,
    specification_root: specificationRoot,
    frozen_contract_pair_digest: null,
    evidence_object_json_schema_id: configuration.evidence_schema_id,
    evidence_object_json_schema_digest: domainDigest(
      EVIDENCE_OBJECT_SCHEMA_DOMAIN,
      schemaFor(configuration.evidence_schema_id),
    ),
    evidence_subject_type: configuration.evidence_subject_type,
    evidence_subject_identity_fields: configuration.evidence_subject_identity_fields || [
      'gate_id',
      'code_commit',
      'runtime_deployment_id',
      'environment',
    ],
    immutable_member_universe_definition: {
      universe_id: configuration.universe_id,
      ordering_rule: 'UTF8_MEMBER_TYPE_THEN_ID',
      duplicate_effect: 'OPEN',
      missing_or_extra_effect: 'OPEN',
    },
    immutable_member_json_schema_set_digest: domainDigest(
      MEMBER_SCHEMA_SET_DOMAIN,
      memberSchemaSet,
    ),
    member_enumerator_executable_digest:
      executableBindings.member_enumerator.executable_digest,
    member_enumerator_configuration_digest:
      executableBindings.member_enumerator.configuration_digest,
    ordered_claim_predicate_definitions: descriptor.ordered_claim_keys.map((claimKey) => ({
      claim_key: claimKey,
      result_type: 'BOOLEAN',
      exact_input_member_types_and_paths:
        executableBindings.predicates[claimKey].exact_inputs,
      measurement_executable_digest:
        executableBindings.predicates[claimKey].executable_digest,
      measurement_configuration_digest:
        executableBindings.predicates[claimKey].configuration_digest,
      comparison_operator: 'EQUALS',
      expected_typed_value: true,
    })),
  };
  const definitionDigest = domainDigest(
    ACCEPTANCE_DEFINITION_ID_DOMAIN,
    acceptanceDefinitionPayload(definition),
  );
  definition.definition_id = definitionDigest;
  definition.definition_digest = definitionDigest;
  return deepFreeze(definition);
}

function createAcceptanceContractBundle({ configurations, specificationRoot }) {
  requireDigest(specificationRoot, 'specification root');
  if (!Array.isArray(configurations) || configurations.length === 0) {
    throw new TypeError('acceptance contract configurations must be non-empty');
  }
  const definitions = [];
  const executableBindings = {};
  for (const configuration of configurations) {
    const bindings = executableBindingsFor(configuration);
    executableBindings[configuration.gate_id] = bindings;
    definitions.push(definitionFor(configuration, specificationRoot, bindings));
  }
  return deepFreeze({
    definitions,
    executable_bindings: executableBindings,
  });
}

function createContainmentContractBundle({ specificationRoot }) {
  return createAcceptanceContractBundle({
    configurations: CONTRACT_CONFIGURATIONS,
    specificationRoot,
  });
}

module.exports = {
  ACCEPTANCE_EXECUTABLE_CLOSURE_DIGEST,
  CONTRACT_CONFIGURATIONS,
  ENUMERATOR_EXECUTABLE_DIGEST,
  createAcceptanceContractBundle,
  createContainmentContractBundle,
  executableBindingsFor,
};

const MARKET_STATS_CONTRACT = 'route-disabled-code-test-live-response/v1';
const BROAD_ROUTE_CONTRACT = 'broad-route-inventory-and-containment/v1';
const {
  SOURCE_CONTAINMENT_INVENTORY_EXECUTABLE_DIGEST,
  sourceContainmentInventory,
} = require('./containment-source-inventory');

const CONTAINMENT_MEMBER_SCHEMA_SETS = Object.freeze({
  [MARKET_STATS_CONTRACT]: Object.freeze([
    Object.freeze({
      member_type: 'ContainedRouteMethodProbe',
      schema_id: 'ContainedRouteMethodProbe/V1',
    }),
    Object.freeze({
      member_type: 'ProgrammeGateTestExecutionRecord',
      schema_id: 'ProgrammeGateTestExecutionRecord/V1',
    }),
  ]),
  [BROAD_ROUTE_CONTRACT]: Object.freeze([
    Object.freeze({
      member_type: 'BroadRouteActionObservation',
      schema_id: 'BroadRouteActionObservation/V1',
    }),
    Object.freeze({
      member_type: 'ProgrammeGateTestExecutionRecord',
      schema_id: 'ProgrammeGateTestExecutionRecord/V1',
    }),
  ]),
});

function contractForDefinition(definition) {
  const contract = definition && definition.evidence_contract;
  if (!Object.hasOwn(CONTAINMENT_MEMBER_SCHEMA_SETS, contract)) {
    throw new Error(`unsupported containment evidence contract: ${contract}`);
  }
  return contract;
}

function member(memberId, memberType, payload) {
  return Object.freeze({
    member_id: memberId,
    member_type: memberType,
    ...(payload === undefined ? {} : { payload }),
  });
}

function expectedForMarketStats(evidenceObject) {
  return [
    ...evidenceObject.method_probes.map((probe) => (
      member(probe.member_id, 'ContainedRouteMethodProbe')
    )),
    ...evidenceObject.tests.map((record) => (
      member(`test:${record.test_id}`, 'ProgrammeGateTestExecutionRecord')
    )),
  ];
}

function expectedForBroadRoutes(evidenceObject) {
  return [
    ...sourceContainmentInventory().map((sourceAction) => (
      member(sourceAction.member_id, 'BroadRouteActionObservation')
    )),
    ...evidenceObject.tests.map((record) => (
      member(`test:${record.test_id}`, 'ProgrammeGateTestExecutionRecord')
    )),
  ];
}

function enumerateContainmentExpectedMembers({ definition, evidenceObject }) {
  const contract = contractForDefinition(definition);
  if (!evidenceObject || typeof evidenceObject !== 'object' || Array.isArray(evidenceObject)) {
    throw new TypeError('containment evidence object must be an object');
  }
  const expected = contract === MARKET_STATS_CONTRACT
    ? expectedForMarketStats(evidenceObject)
    : expectedForBroadRoutes(evidenceObject);
  return Object.freeze(expected);
}

function containmentMembers({ definition, evidenceObject }) {
  const contract = contractForDefinition(definition);
  const observations = contract === MARKET_STATS_CONTRACT
    ? evidenceObject.method_probes.map((probe) => (
        member(probe.member_id, 'ContainedRouteMethodProbe', probe)
      ))
    : evidenceObject.routes.map((observation) => (
        member(observation.member_id, 'BroadRouteActionObservation', observation)
      ));
  return Object.freeze([
    ...observations,
    ...evidenceObject.tests.map((record) => (
      member(`test:${record.test_id}`, 'ProgrammeGateTestExecutionRecord', record)
    )),
  ]);
}

function memberSchemaSetForContract(evidenceContract) {
  const schemaSet = CONTAINMENT_MEMBER_SCHEMA_SETS[evidenceContract];
  if (!schemaSet) {
    throw new Error(`unsupported containment evidence contract: ${evidenceContract}`);
  }
  return schemaSet;
}

module.exports = {
  BROAD_ROUTE_CONTRACT,
  CONTAINMENT_MEMBER_SCHEMA_SETS,
  MARKET_STATS_CONTRACT,
  SOURCE_CONTAINMENT_INVENTORY_EXECUTABLE_DIGEST,
  containmentMembers,
  enumerateContainmentExpectedMembers,
  memberSchemaSetForContract,
};

const { execFile } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const { promisify } = require('node:util');

const execFileAsync = promisify(execFile);

async function runCommand(command, args, options = {}) {
  const startedAt = new Date().toISOString();
  try {
    const result = await execFileAsync(command, args, {
      cwd: options.cwd,
      encoding: 'utf8',
      maxBuffer: 32 * 1024 * 1024,
      env: options.env,
    });
    return Object.freeze({
      started_at: startedAt,
      completed_at: new Date().toISOString(),
      exit_code: 0,
      stdout: result.stdout || '',
      stderr: result.stderr || '',
    });
  } catch (error) {
    return Object.freeze({
      started_at: startedAt,
      completed_at: new Date().toISOString(),
      exit_code: Number.isInteger(error.code) ? error.code : 1,
      stdout: error.stdout || '',
      stderr: error.stderr || String(error.message || error),
    });
  }
}

const CONTAINMENT_RUNTIME = Object.freeze({
  readFile(file) {
    return fs.readFileSync(file);
  },
  fileExists(file) {
    return fs.existsSync(file);
  },
  resolve(...parts) {
    return path.resolve(...parts);
  },
  now() {
    return new Date();
  },
  fetch(input, init) {
    return fetch(input, init);
  },
  runCommand,
});

function validateDeploymentBinding({
  deployment,
  originDeployment,
  deploymentId,
  environment,
  codeCommit,
  specificationRoot,
}) {
  if (!deployment || typeof deployment !== 'object' || Array.isArray(deployment)) {
    throw new TypeError('Vercel deployment inspection must be an object');
  }
  if (
    !originDeployment
    || typeof originDeployment !== 'object'
    || Array.isArray(originDeployment)
    || originDeployment.id !== deploymentId
    || originDeployment.readyState !== 'READY'
  ) {
    throw new Error('the production origin does not resolve to the READY deployment ID');
  }
  if (deployment.id !== deploymentId || deployment.readyState !== 'READY') {
    throw new Error('the deployment API did not return the supplied READY deployment ID');
  }
  if (
    (environment === 'PRODUCTION' && deployment.target !== 'production')
    || (environment === 'STAGING' && deployment.target === 'production')
  ) {
    throw new Error('the deployment target does not match the evidence environment');
  }
  if (deployment.meta?.programmeCodeCommit !== codeCommit) {
    throw new Error('the deployment metadata does not bind the exact code commit');
  }
  if (deployment.meta?.programmeSpecificationRoot !== specificationRoot) {
    throw new Error('the deployment metadata does not bind the exact specification root');
  }
  return true;
}

module.exports = {
  CONTAINMENT_RUNTIME,
  runCommand,
  validateDeploymentBinding,
};

const {
  domainDigest,
} = require('./bytes');
const {
  createContainmentContractBundle,
} = require('./containment-contracts');
const {
  enumerateContainmentExpectedMembers,
} = require('./containment-enumerator');
const {
  buildContainmentEvidenceSigningRequest,
  createContainmentSigningRequestAuthority,
} = require('./containment-signing-request');
const {
  enumerateClosedMembers,
} = require('./enumerate');
const {
  ACCEPTANCE_PREDICATES,
  evaluateAcceptanceClaims,
} = require('./predicates');
const {
  REGISTRY_DIGESTS,
  VALIDATOR_CONFIGURATION,
  acceptanceDescriptorForContract,
} = require('./registry');
const {
  SCHEMA_IDS,
  schemaFor,
  validateSchema,
} = require('./schema-registry');
const {
  verifySignature,
} = require('./signatures');
const {
  createProgrammeGateEvidenceValidator,
} = require('./validator');

const SIGNING_REQUEST_DOMAIN = 'PROGRAMME_GATE_CONTAINMENT_SIGNING_REQUEST/V1';
const CONTRACT_DEFINITION_SET_DOMAIN =
  'PROGRAMME_GATE_CONTAINMENT_ACCEPTANCE_DEFINITION_SET/V1';
const EXECUTABLE_BINDING_SET_DOMAIN =
  'PROGRAMME_GATE_CONTAINMENT_EXECUTABLE_BINDING_SET/V1';
const DIGEST_PATTERN = /^[a-f0-9]{64}$/;
const authorityBrands = new WeakSet();

function requireExactKeys(value, keys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  if (actual.length !== expected.length
    || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${label} does not match its closed input`);
  }
}

function requireTimestamp(value, label) {
  if (typeof value !== 'string'
    || !Number.isFinite(Date.parse(value))
    || new Date(value).toISOString() !== value) {
    throw new TypeError(`${label} must be a canonical UTC timestamp`);
  }
  return value;
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function createContainmentSignedPreflightAuthority(input) {
  requireExactKeys(input, [
    'keyRegistry',
    'validatorExecutableDigests',
    'verificationTime',
  ], 'containment signed-evidence preflight authority');
  validateSchema('TrustedProgrammeGatePublicKeys/V1', input.keyRegistry);
  if (input.keyRegistry.registry_state !== 'ACTIVE') {
    throw new Error('trusted public-key registry is not active');
  }
  if (!Array.isArray(input.validatorExecutableDigests)
    || input.validatorExecutableDigests.length === 0
    || new Set(input.validatorExecutableDigests).size
      !== input.validatorExecutableDigests.length
    || input.validatorExecutableDigests.some(
      (digest) => typeof digest !== 'string' || !DIGEST_PATTERN.test(digest),
    )) {
    throw new TypeError('validator executable digests must be a non-empty closed digest set');
  }
  const authority = deepFreeze({
    keyRegistry: structuredClone(input.keyRegistry),
    validatorExecutableDigests: [...input.validatorExecutableDigests],
    verificationTime: requireTimestamp(input.verificationTime, 'verification time'),
  });
  authorityBrands.add(authority);
  return authority;
}

function requireAuthority(value) {
  if (!authorityBrands.has(value)) {
    throw new TypeError('a closed containment signed-evidence preflight authority is required');
  }
  return value;
}

function openValidation(gateId, reasonCode, reason) {
  return Object.freeze({
    valid: false,
    state: 'OPEN',
    gate_id: typeof gateId === 'string' ? gateId : null,
    evidence_envelope_id: null,
    evidence_payload_digest: null,
    reason_code: reasonCode,
    reason,
  });
}

function preflightResult({ gateId, validation, signedEnvelope = null }) {
  return deepFreeze({
    preflight_type: 'ProgrammeGateContainmentSignedEvidencePreflight/V1',
    gate_id: gateId,
    evidence_validation: validation,
    signed_envelope: validation.valid === true ? signedEnvelope : null,
    evidence_validation_state: validation.state,
    formal_gate_state: 'OPEN',
    private_key_used: false,
    status_publication_attempted: false,
  });
}

function matchingReadinessContracts(bundle) {
  const contracts = createContainmentContractBundle({
    specificationRoot: bundle.specification_root,
  });
  if (domainDigest(CONTRACT_DEFINITION_SET_DOMAIN, bundle.acceptance_definitions)
      !== domainDigest(CONTRACT_DEFINITION_SET_DOMAIN, contracts.definitions)
    || domainDigest(EXECUTABLE_BINDING_SET_DOMAIN, bundle.executable_bindings)
      !== domainDigest(EXECUTABLE_BINDING_SET_DOMAIN, contracts.executable_bindings)) {
    throw new Error('containment readiness contracts have drifted');
  }
  return contracts;
}

function preflightContainmentEvidenceSignature(input) {
  requireExactKeys(input, [
    'authority',
    'bundle',
    'candidate',
    'gate',
    'signature',
    'signingRequest',
  ], 'containment signed-evidence preflight');
  const authority = requireAuthority(input.authority);
  const gateId = input.gate && input.gate.id;
  let expectedRequest;
  let contracts;
  try {
    const requestEnvelope = input.signingRequest
      && input.signingRequest.unsigned_envelope;
    if (!requestEnvelope
      || !authority.validatorExecutableDigests.includes(
        requestEnvelope.validator_executable_digest,
      )
      || requestEnvelope.validator_configuration_digest
        !== REGISTRY_DIGESTS.validator_configuration) {
      throw new Error('signing request uses an unregistered validator');
    }
    const signingAuthority = createContainmentSigningRequestAuthority({
      keyRegistry: authority.keyRegistry,
      validatorConfigurationDigest: requestEnvelope.validator_configuration_digest,
      validatorExecutableDigest: requestEnvelope.validator_executable_digest,
      validatorKeyId: requestEnvelope.validator_key_id,
      verificationTime: authority.verificationTime,
    });
    expectedRequest = buildContainmentEvidenceSigningRequest({
      authority: signingAuthority,
      bundle: input.bundle,
      candidate: input.candidate,
      gate: input.gate,
    });
    if (domainDigest(SIGNING_REQUEST_DOMAIN, input.signingRequest)
      !== domainDigest(SIGNING_REQUEST_DOMAIN, expectedRequest)) {
      throw new Error('signing request does not match exact readiness');
    }
    contracts = matchingReadinessContracts(input.bundle);
  } catch {
    return preflightResult({
      gateId,
      validation: openValidation(
        gateId,
        'SIGNING_REQUEST_MISMATCH',
        'The external signature request does not match exact containment readiness.',
      ),
    });
  }

  const signedEnvelope = {
    ...expectedRequest.unsigned_envelope,
    signature: input.signature,
  };
  const validateEvidence = createProgrammeGateEvidenceValidator({
    domainDigest,
    validateSchema,
    schemaFor,
    knownSchemaIds: SCHEMA_IDS,
    acceptanceDescriptorForContract,
    acceptanceDefinitions: contracts.definitions,
    enumerateClosedMembers,
    enumerateExpectedMembers: enumerateContainmentExpectedMembers,
    evaluateAcceptanceClaims,
    predicateRegistry: ACCEPTANCE_PREDICATES,
    verifySignature,
    validatorConfiguration: VALIDATOR_CONFIGURATION,
    allowedValidatorExecutableDigests: authority.validatorExecutableDigests,
    executableBindings: contracts.executable_bindings,
    keyRegistry: authority.keyRegistry,
  });
  const validation = validateEvidence({
    gate: input.gate,
    envelope: signedEnvelope,
    evidenceSubject: input.candidate.evidence_subject,
    evidenceObject: input.candidate.evidence_object,
    members: input.candidate.members,
    memberSchemaSet: input.candidate.member_schema_set,
    testResults: input.candidate.test_results,
    expectedSpecificationRoot: input.bundle.specification_root,
    expectedFrozenContractPairDigest: null,
    expectedCodeCommit: input.bundle.code_commit,
    expectedEnvironment: input.bundle.environment,
    clock: { now: () => authority.verificationTime },
  });
  return preflightResult({
    gateId,
    validation,
    signedEnvelope,
  });
}

module.exports = {
  createContainmentSignedPreflightAuthority,
  preflightContainmentEvidenceSignature,
};

