const DIGEST_PATTERN = /^[a-f0-9]{64}$/;
const authorityBrands = new WeakSet();

function requireExactKeys(value, keys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  if (actual.length !== expected.length
    || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${label} does not match its closed input`);
  }
}

function requireDigest(value, label) {
  if (typeof value !== 'string' || !DIGEST_PATTERN.test(value)) {
    throw new TypeError(`${label} must be a SHA-256 digest`);
  }
  return value;
}

function compareUtf8(left, right) {
  return Buffer.compare(Buffer.from(left, 'utf8'), Buffer.from(right, 'utf8'));
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function requireTrustedPublicKeyBinding({
  keyRegistry,
  validatorKeyId,
  verificationTime,
}) {
  validateSchema('TrustedProgrammeGatePublicKeys/V1', keyRegistry);
  if (keyRegistry.registry_state !== 'ACTIVE') {
    throw new Error('trusted public-key registry is not active');
  }
  const matches = keyRegistry.keys.filter((entry) => entry.key_id === validatorKeyId);
  if (matches.length !== 1) {
    throw new Error('validator key ID is not uniquely trusted');
  }
  const key = matches[0];
  if (!key.permitted_roles.includes(EVIDENCE_SIGNATURE_ROLE)
    || !key.permitted_domains.includes(EVIDENCE_SIGNATURE_DOMAIN)) {
    throw new Error('validator key does not permit the evidence signature role and domain');
  }
  const observed = Date.parse(verificationTime);
  const validFrom = Date.parse(key.valid_from);
  const validUntil = Date.parse(key.valid_until);
  const revokedAt = key.revoked_at === null ? null : Date.parse(key.revoked_at);
  if (!Number.isFinite(observed)
    || !Number.isFinite(validFrom)
    || !Number.isFinite(validUntil)
    || observed < validFrom
    || observed >= validUntil
    || (revokedAt !== null && observed >= revokedAt)) {
    throw new Error('validator key is not valid at the signing-request time');
  }
  if (crypto.createPublicKey(key.public_key_pem).asymmetricKeyType !== 'ed25519') {
    throw new Error('validator key must be Ed25519');
  }
}

function createContainmentSigningRequestAuthority(input) {
  requireExactKeys(input, [
    'keyRegistry',
    'validatorConfigurationDigest',
    'validatorExecutableDigest',
    'validatorKeyId',
    'verificationTime',
  ], 'containment signing-request authority');
  requireDigest(input.validatorExecutableDigest, 'validator executable digest');
  requireDigest(input.validatorConfigurationDigest, 'validator configuration digest');
  if (input.validatorConfigurationDigest !== REGISTRY_DIGESTS.validator_configuration) {
    throw new Error('validator configuration digest is not the registered configuration');
  }
  if (typeof input.validatorKeyId !== 'string' || input.validatorKeyId.length === 0) {
    throw new TypeError('validator key ID must be non-empty');
  }
  requireTrustedPublicKeyBinding({
    keyRegistry: input.keyRegistry,
    validatorKeyId: input.validatorKeyId,
    verificationTime: input.verificationTime,
  });
  const authority = deepFreeze({
    keyRegistry: structuredClone(input.keyRegistry),
    validatorConfigurationDigest: input.validatorConfigurationDigest,
    validatorExecutableDigest: input.validatorExecutableDigest,
    validatorKeyId: input.validatorKeyId,
    verificationTime: new Date(input.verificationTime).toISOString(),
  });
  authorityBrands.add(authority);
  return authority;
}

function requireAuthority(value) {
  if (!authorityBrands.has(value)) {
    throw new TypeError('a closed containment signing-request authority is required');
  }
  return value;
}

function definitionFor(bundle, candidate) {
  const matches = bundle.acceptance_definitions.filter(
    (definition) => definition.evidence_contract === candidate.evidence_contract,
  );
  if (matches.length !== 1) {
    throw new Error('candidate does not resolve to one acceptance definition');
  }
  const definition = matches[0];
  if (candidate.acceptance_definition_id !== definition.definition_id) {
    throw new Error('candidate acceptance definition has drifted');
  }
  validateSchema('ProgrammeGateAcceptanceDefinition/V1', definition);
  return definition;
}

function evidenceSubjectIdentity(subject, fields) {
  const identity = {};
  for (const field of fields) {
    if (!Object.hasOwn(subject, field)) {
      throw new Error(`evidence subject is missing identity field ${field}`);
    }
    identity[field] = subject[field];
  }
  return identity;
}

function validateCandidateEvidence({
  authority,
  bundle,
  candidate,
  definition,
  gate,
  orderedMembers,
  orderedTests,
}) {
  validateSchema(definition.evidence_object_json_schema_id, candidate.evidence_object);
  const subject = candidate.evidence_subject;
  if (subject.gate_id !== gate.id
    || subject.code_commit !== bundle.code_commit
    || subject.runtime_deployment_id !== bundle.runtime_deployment_id
    || subject.environment !== bundle.environment
    || subject.observed_at !== bundle.observed_at
    || candidate.evidence_object.observed_at !== bundle.observed_at) {
    throw new Error('containment evidence subject has drifted from the bundle');
  }
  const expectedMemberSchemaSet = memberSchemaSetForContract(gate.evidence_contract);
  if (domainDigest(MEMBER_SCHEMA_SET_DOMAIN, candidate.member_schema_set)
    !== definition.immutable_member_json_schema_set_digest
    || domainDigest(MEMBER_SCHEMA_SET_DOMAIN, expectedMemberSchemaSet)
      !== definition.immutable_member_json_schema_set_digest) {
    throw new Error('containment member schema set has drifted');
  }
  for (const member of orderedMembers) {
    const binding = expectedMemberSchemaSet.find(
      (entry) => entry.member_type === member.member_type,
    );
    if (!binding) throw new Error(`unbound containment member type ${member.member_type}`);
    validateSchema(binding.schema_id, member.payload);
  }
  const evidenceTests = [...candidate.evidence_object.tests].sort(
    (left, right) => compareUtf8(left.test_id, right.test_id),
  );
  if (domainDigest(TEST_RESULT_ROOT_DOMAIN, orderedTests)
    !== domainDigest(TEST_RESULT_ROOT_DOMAIN, evidenceTests)) {
    throw new Error('containment test executions have drifted');
  }
  const recomputedClaims = evaluateAcceptanceClaims({
    gate_id: gate.id,
    evidence: candidate.evidence_object,
    context: {
      specificationRoot: bundle.specification_root,
      codeCommit: bundle.code_commit,
      environment: bundle.environment,
      expectedSpecificationRoot: bundle.specification_root,
      expectedCodeCommit: bundle.code_commit,
      expectedEnvironment: bundle.environment,
      observed_at: bundle.observed_at,
      clock: { now: () => authority.verificationTime },
    },
  });
  if (domainDigest('PROGRAMME_GATE_ACCEPTANCE_CLAIMS/V1', recomputedClaims)
    !== domainDigest(
      'PROGRAMME_GATE_ACCEPTANCE_CLAIMS/V1',
      candidate.exact_acceptance_claims,
    )
    || recomputedClaims.some((claim) => claim.typed_value !== true)) {
    throw new Error('containment acceptance claims are not exact passing measurements');
  }
}

function buildContainmentEvidenceSigningRequest(input) {
  requireExactKeys(
    input,
    ['authority', 'bundle', 'candidate', 'gate'],
    'containment evidence signing request',
  );
  const authority = requireAuthority(input.authority);
  const { bundle, candidate, gate } = input;
  if (bundle.readiness_state !== 'READY_FOR_SIGNATURE'
    || bundle.formal_gate_state !== 'OPEN'
    || bundle.private_key_used !== false
    || bundle.status_publication_attempted !== false
    || candidate.readiness_state !== 'READY_FOR_SIGNATURE'
    || candidate.formal_gate_state !== 'OPEN'
    || candidate.signature !== null) {
    throw new Error('only unsigned OPEN readiness can become a signing request');
  }
  if (candidate.gate_id !== gate.id
    || candidate.evidence_contract !== gate.evidence_contract
    || candidate.evidence_object.gate_id !== gate.id) {
    throw new Error('containment candidate has inconsistent gate or runtime bindings');
  }
  if (bundle.code_commit !== candidate.evidence_object.code_commit
    || bundle.environment !== candidate.evidence_object.environment
    || bundle.runtime_deployment_id !== candidate.evidence_object.runtime_deployment_id) {
    throw new Error('containment candidate has inconsistent bundle bindings');
  }

  const definition = definitionFor(bundle, candidate);
  const expectedMembers = enumerateContainmentExpectedMembers({
    definition,
    evidenceObject: candidate.evidence_object,
  });
  const orderedMembers = enumerateClosedMembers({
    expectedMembers,
    members: candidate.members,
  });
  const orderedTests = [...candidate.test_results].sort(
    (left, right) => compareUtf8(left.test_id, right.test_id),
  );
  validateCandidateEvidence({
    authority,
    bundle,
    candidate,
    definition,
    gate,
    orderedMembers,
    orderedTests,
  });
  const subjectIdentity = evidenceSubjectIdentity(
    candidate.evidence_subject,
    definition.evidence_subject_identity_fields,
  );
  const unsignedEnvelope = {
    schema_version: 'ProgrammeGateEvidenceEnvelope/V2',
    gate_id: gate.id,
    evidence_contract: gate.evidence_contract,
    acceptance_definition_id: definition.definition_id,
    acceptance_definition_digest: definition.definition_digest,
    specification_root: bundle.specification_root,
    code_commit: bundle.code_commit,
    environment: bundle.environment,
    evidence_subject_type: definition.evidence_subject_type,
    evidence_subject_id: domainDigest(
      EVIDENCE_SUBJECT_ID_DOMAIN,
      subjectIdentity,
    ),
    evidence_subject_payload_digest: domainDigest(
      EVIDENCE_SUBJECT_PAYLOAD_DOMAIN,
      candidate.evidence_subject,
    ),
    required_evidence_object_type: gate.required_evidence_object_type,
    required_evidence_object_payload_digest: domainDigest(
      EVIDENCE_OBJECT_PAYLOAD_DOMAIN,
      candidate.evidence_object,
    ),
    exact_acceptance_claims: candidate.exact_acceptance_claims,
    immutable_member_root: domainDigest(
      IMMUTABLE_MEMBER_ROOT_DOMAIN,
      orderedMembers,
    ),
    test_result_root: domainDigest(TEST_RESULT_ROOT_DOMAIN, orderedTests),
    validator_executable_digest: authority.validatorExecutableDigest,
    validator_configuration_digest: authority.validatorConfigurationDigest,
    validator_key_id: authority.validatorKeyId,
    terminal_state: 'PASS',
    signature_algorithm: 'Ed25519',
  };
  validateSchema('ProgrammeGateEvidenceEnvelope/V2', {
    ...unsignedEnvelope,
    signature: 'AA==',
  });
  const signingFrame = signatureBytes({
    domain: EVIDENCE_SIGNATURE_DOMAIN,
    role: EVIDENCE_SIGNATURE_ROLE,
    payload: unsignedEnvelope,
  });
  return deepFreeze({
    request_type: 'ProgrammeGateEvidenceSigningRequest/V1',
    gate_id: gate.id,
    unsigned_envelope: unsignedEnvelope,
    signing_domain: EVIDENCE_SIGNATURE_DOMAIN,
    signing_role: EVIDENCE_SIGNATURE_ROLE,
    signing_frame_sha256: crypto.createHash('sha256').update(signingFrame).digest('hex'),
    signing_frame_base64: signingFrame.toString('base64'),
    readiness_state: 'READY_FOR_EXTERNAL_SIGNATURE',
    formal_gate_state: 'OPEN',
    private_key_used: false,
    signature: null,
  });
}

module.exports = {
  buildContainmentEvidenceSigningRequest,
  createContainmentSigningRequestAuthority,
};

const {
  BROAD_CORPUS_CONTAINED_ROUTES,
  BROAD_CORPUS_CONTAINED_ROUTE_FILES,
} = require('../broad-corpus-containment');
const {
  QUERY_CONTAINED_ROUTES,
  QUERY_CONTAINED_ROUTE_FILES,
} = require('../query-containment');
const { SERVICE_CLIENT_ROUTE_ACTIONS } = require('../service-client-route-actions');
const { domainDigest } = require('./bytes');

const HTTP_METHODS = Object.freeze([
  'GET',
  'POST',
  'PUT',
  'PATCH',
  'DELETE',
  'OPTIONS',
  'HEAD',
]);

function compareText(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function actionId(method, route) {
  return `${method} ${route}`;
}

function actionMethods(value) {
  return Array.isArray(value) ? value : [value];
}

function sourceContainmentInventory() {
  const actions = new Map();
  function add(route, method, containmentClass, file) {
    const memberId = actionId(method, route);
    const current = actions.get(memberId);
    if (current && current.file !== file) {
      throw new Error(`${memberId} maps to more than one route file`);
    }
    if (!current) {
      actions.set(memberId, {
        member_id: memberId,
        route_id: route,
        method,
        containment_class: containmentClass,
        file,
      });
    }
  }

  for (const route of QUERY_CONTAINED_ROUTES) {
    for (const method of HTTP_METHODS) {
      add(route, method, 'QUERY_ROUTE', QUERY_CONTAINED_ROUTE_FILES[route]);
    }
  }
  for (const [route, methods] of Object.entries(BROAD_CORPUS_CONTAINED_ROUTES)) {
    for (const method of actionMethods(methods)) {
      add(route, method, 'BROAD_CORPUS_ACTION', BROAD_CORPUS_CONTAINED_ROUTE_FILES[route]);
    }
  }
  for (const descriptor of SERVICE_CLIENT_ROUTE_ACTIONS) {
    if (descriptor.route === '/api/market-stats') continue;
    for (const routeAction of descriptor.actions) {
      if (routeAction.disposition !== 'HARD_CONTAIN') continue;
      add(
        descriptor.route,
        routeAction.method,
        'PUBLIC_SERVICE_ACTION',
        descriptor.file,
      );
    }
  }
  return Object.freeze([...actions.values()].sort(
    (left, right) => compareText(left.member_id, right.member_id),
  ).map(Object.freeze));
}

const SOURCE_CONTAINMENT_INVENTORY_EXECUTABLE_DIGEST = domainDigest(
  'PROGRAMME_GATE_SOURCE_CONTAINMENT_INVENTORY_EXECUTABLE/V1',
  {
    http_methods: HTTP_METHODS,
    source: sourceContainmentInventory.toString(),
    action_id_source: actionId.toString(),
    action_methods_source: actionMethods.toString(),
  },
);

module.exports = {
  HTTP_METHODS,
  SOURCE_CONTAINMENT_INVENTORY_EXECUTABLE_DIGEST,
  actionId,
  sourceContainmentInventory,
};

const fs = require('node:fs');
const YAML = require('yaml');

const {
  domainDigest,
} = require('./bytes');
const {
  createContainmentContractBundle,
} = require('./containment-contracts');
const {
  enumerateContainmentExpectedMembers,
} = require('./containment-enumerator');
const {
  enumerateClosedMembers,
} = require('./enumerate');
const {
  createGoverningRegistryAuthority,
} = require('./governing-registry');
const {
  ACCEPTANCE_PREDICATES,
  evaluateAcceptanceClaims,
} = require('./predicates');
const {
  REGISTRY_DIGESTS,
  VALIDATOR_CONFIGURATION,
  acceptanceDescriptorForContract,
} = require('./registry');
const {
  SCHEMA_IDS,
  schemaFor,
  validateSchema,
} = require('./schema-registry');
const {
  verifySignature,
} = require('./signatures');
const {
  buildUnsignedProgrammeGateStatus,
  createProgrammeStatusAuthority,
} = require('./status');
const {
  createProgrammeGateEvidenceValidator,
  unsignedEnvelope,
} = require('./validator');

const CONTAINMENT_GATE_IDS = Object.freeze([
  'G0_MARKET_STATS_CONTAINED',
  'G0_BROAD_CORPUS_ROUTES_CONTAINED',
]);
const DIGEST_PATTERN = /^[a-f0-9]{64}$/;
const COMMIT_PATTERN = /^[a-f0-9]{40}$/;
const authorityBrands = new WeakSet();

function requireExactKeys(value, keys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  if (actual.length !== expected.length
    || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${label} does not match its closed input`);
  }
}

function requirePattern(value, pattern, label) {
  if (typeof value !== 'string' || !pattern.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function requireTimestamp(value, label) {
  if (typeof value !== 'string'
    || !Number.isFinite(Date.parse(value))
    || new Date(value).toISOString() !== value) {
    throw new TypeError(`${label} must be a canonical UTC timestamp`);
  }
  return value;
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function createContainmentStatusReadinessAuthority(input) {
  requireExactKeys(input, [
    'codeCommit',
    'environment',
    'keyRegistry',
    'specificationRoot',
    'validatorExecutableDigest',
    'validatorKeyId',
    'verificationTime',
  ], 'containment status-readiness authority');
  const specificationRoot = requirePattern(
    input.specificationRoot,
    DIGEST_PATTERN,
    'specification root',
  );
  const codeCommit = requirePattern(input.codeCommit, COMMIT_PATTERN, 'code commit');
  const validatorExecutableDigest = requirePattern(
    input.validatorExecutableDigest,
    DIGEST_PATTERN,
    'validator executable digest',
  );
  if (!['STAGING', 'PRODUCTION'].includes(input.environment)) {
    throw new Error('environment must be STAGING or PRODUCTION');
  }
  if (typeof input.validatorKeyId !== 'string' || input.validatorKeyId.length === 0) {
    throw new TypeError('validator key ID must be non-empty');
  }
  validateSchema('TrustedProgrammeGatePublicKeys/V1', input.keyRegistry);
  if (input.keyRegistry.registry_state !== 'ACTIVE') {
    throw new Error('trusted public-key registry is not active');
  }
  const verificationTime = requireTimestamp(input.verificationTime, 'verification time');
  const contracts = createContainmentContractBundle({ specificationRoot });
  const governingRegistryAuthority = createGoverningRegistryAuthority({
    readFileSync: fs.readFileSync,
    parseYaml: YAML.parse,
    domainDigest,
  });
  const validateEvidence = createProgrammeGateEvidenceValidator({
    domainDigest,
    validateSchema,
    schemaFor,
    knownSchemaIds: SCHEMA_IDS,
    acceptanceDescriptorForContract,
    acceptanceDefinitions: contracts.definitions,
    enumerateClosedMembers,
    enumerateExpectedMembers: enumerateContainmentExpectedMembers,
    evaluateAcceptanceClaims,
    predicateRegistry: ACCEPTANCE_PREDICATES,
    verifySignature,
    validatorConfiguration: VALIDATOR_CONFIGURATION,
    allowedValidatorExecutableDigests: [validatorExecutableDigest],
    executableBindings: contracts.executable_bindings,
    keyRegistry: structuredClone(input.keyRegistry),
  });
  const statusAuthority = createProgrammeStatusAuthority({
    governingRegistryAuthority,
    domainDigest,
    validateEvidence(candidateInput) {
      return validateEvidence({
        ...candidateInput,
        expectedSpecificationRoot: specificationRoot,
        expectedFrozenContractPairDigest: null,
        expectedCodeCommit: codeCommit,
        expectedEnvironment: input.environment,
        clock: { now: () => verificationTime },
      });
    },
    evidencePayloadForDigest: unsignedEnvelope,
    validateStatusSchema: validateSchema,
    verifyStatusSignature: () => false,
    validatorExecutableDigest,
    validatorConfigurationDigest: REGISTRY_DIGESTS.validator_configuration,
    validatorKeyId: input.validatorKeyId,
    bootstrapState: 'AVAILABLE',
    terminalPairState: 'UNVALIDATED',
  });
  const authority = deepFreeze({
    specificationRoot,
    codeCommit,
    environment: input.environment,
    validatorExecutableDigest,
    validatorKeyId: input.validatorKeyId,
    verificationTime,
    statusAuthority,
  });
  authorityBrands.add(authority);
  return authority;
}

function requireAuthority(value) {
  if (!authorityBrands.has(value)) {
    throw new TypeError('a closed containment status-readiness authority is required');
  }
  return value;
}

function candidateForStatus(candidate, signedPreflight) {
  if (!signedPreflight
    || signedPreflight.preflight_type
      !== 'ProgrammeGateContainmentSignedEvidencePreflight/V1'
    || signedPreflight.gate_id !== candidate.gate_id
    || !signedPreflight.signed_envelope) {
    throw new Error(`signed containment preflight is missing for ${candidate.gate_id}`);
  }
  return Object.freeze({
    envelope: structuredClone(signedPreflight.signed_envelope),
    validation_input: Object.freeze({
      evidenceSubject: structuredClone(candidate.evidence_subject),
      evidenceObject: structuredClone(candidate.evidence_object),
      members: structuredClone(candidate.members),
      memberSchemaSet: structuredClone(candidate.member_schema_set),
      testResults: structuredClone(candidate.test_results),
    }),
  });
}

function buildContainmentStatusReadiness(input) {
  requireExactKeys(
    input,
    ['authority', 'bundle', 'signedPreflights'],
    'containment status readiness',
  );
  const authority = requireAuthority(input.authority);
  const { bundle } = input;
  if (!bundle
    || bundle.specification_root !== authority.specificationRoot
    || bundle.code_commit !== authority.codeCommit
    || bundle.environment !== authority.environment
    || bundle.formal_gate_state !== 'OPEN'
    || bundle.status_publication_attempted !== false
    || !Array.isArray(bundle.candidates)
    || bundle.candidates.length !== CONTAINMENT_GATE_IDS.length
    || !Array.isArray(input.signedPreflights)
    || input.signedPreflights.length !== CONTAINMENT_GATE_IDS.length) {
    throw new Error('containment readiness bundle does not match the closed authority');
  }
  const candidateIds = bundle.candidates.map((candidate) => candidate.gate_id);
  if (candidateIds.some((gateId, index) => gateId !== CONTAINMENT_GATE_IDS[index])) {
    throw new Error('containment readiness candidates do not match the closed gate order');
  }
  const preflightByGate = new Map(
    input.signedPreflights.map((preflight) => [preflight && preflight.gate_id, preflight]),
  );
  if (preflightByGate.size !== CONTAINMENT_GATE_IDS.length) {
    throw new Error('signed containment preflights are missing or duplicated');
  }
  const evidenceCandidates = bundle.candidates.map((candidate) => candidateForStatus(
    candidate,
    preflightByGate.get(candidate.gate_id),
  ));
  const unsignedStatus = buildUnsignedProgrammeGateStatus({
    authority: authority.statusAuthority,
    evidenceCandidates,
    specificationRoot: authority.specificationRoot,
    codeCommit: authority.codeCommit,
    environment: authority.environment,
    generation: 1,
    predecessorStatusId: 'NONE',
  });
  const passingGateIds = unsignedStatus.ordered_gate_projection
    .filter((row) => row.state === 'PASS')
    .map((row) => row.gate_id);
  const exactContainmentPass = passingGateIds.length === CONTAINMENT_GATE_IDS.length
    && passingGateIds.every((gateId, index) => gateId === CONTAINMENT_GATE_IDS[index]);
  return deepFreeze({
    readiness_type: 'ProgrammeGateContainmentStatusReadiness/V1',
    readiness_state: exactContainmentPass
      ? 'READY_FOR_REMAINING_G0_EVIDENCE'
      : 'OPEN',
    passing_gate_ids: passingGateIds,
    unsigned_status: unsignedStatus,
    status_signature: null,
    formal_status_state: 'OPEN',
    bootstrap_nonce_consumed: false,
    status_publication_attempted: false,
  });
}

module.exports = {
  CONTAINMENT_GATE_IDS,
  buildContainmentStatusReadiness,
  createContainmentStatusReadinessAuthority,
};

