  'lane_id',
  'exact_specification_root',
  'frozen_specification',
  'registered_prompt',
  'output_schema',
]);
const FROZEN_SPECIFICATION_KEYS = Object.freeze([
  'manifest_id',
  'manifest_digest',
  'file_count',
  'ordered_members',
  'immutable',
]);
const FROZEN_SPECIFICATION_MEMBER_KEYS = Object.freeze([
