  'review_runtime_version',
  'review_runtime_binary_digest',
  'controller_run_root',
  'lane_run_root',
  'working_directory',
  'operating_system',
  'architecture',
  'home_path',
  'codex_home_path',
  'tmpdir_path',
  'path_value',
  'lang',
  'lc_all',
  'term',
]);
const PLAN_INPUT_KEYS = Object.freeze([
  'controller_version',
  'controller_run_id',
  'immutable_task_id',
  'nonce',
  'controller_key_id',
  'task_manifest',
  'runtime_context',
