  'parent_session_state',
  'no_earlier_review_conclusions_were_inputs',
  'fresh_cli_session_observed',
  'read_only_execution_observed',
  'controller_direct_execution_observed',
]);

function requireExactKeys(value, expectedKeys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const keys = Object.keys(value);
  const extra = keys.filter((key) => !expectedKeys.includes(key));
  const missing = expectedKeys.filter((key) => !keys.includes(key));
  if (extra.length > 0) throw new Error(`${label} has unsupported fields: ${extra.join(', ')}`);
  if (missing.length > 0) throw new Error(`${label} is missing fields: ${missing.join(', ')}`);
}

function requireNonEmptyString(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function requireToken(value, label) {
  if (typeof value !== 'string' || !TOKEN_PATTERN.test(value)) {
    throw new TypeError(`${label} must be an uppercase token`);
  }
  return value;
}

function requireDigest(value, label) {
  if (typeof value !== 'string' || !DIGEST_PATTERN.test(value)) {
    throw new TypeError(`${label} must be a SHA-256 digest`);
  }
  return value;
}

function requireNonNegativeInteger(value, label) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${label} must be a non-negative safe integer`);
  }
  return value;
}

function requireAbsolutePath(value, label) {
  requireNonEmptyString(value, label);
  if (!path.isAbsolute(value) || path.normalize(value) !== value) {
    throw new TypeError(`${label} must be a normalised absolute path`);
  }
  return value;
}

function exactSourceBytes(sourceBytesBase64, label) {
  requireNonEmptyString(sourceBytesBase64, `${label} source bytes`);
  const bytes = Buffer.from(sourceBytesBase64, 'base64');
  if (bytes.length === 0 || bytes.toString('base64') !== sourceBytesBase64) {
    throw new TypeError(`${label} source bytes must use canonical base64`);
  }
  return bytes;
}

function specificationRootFromMembers(members) {
  if (!Array.isArray(members) || members.length === 0) {
    throw new TypeError('frozen specification ordered members must be non-empty');
  }
  const records = members.map((member, index) => {
    requireExactKeys(
      member,
      FROZEN_SPECIFICATION_MEMBER_KEYS,
      `frozen specification member ${index + 1}`,
    );
    if (member.order !== index + 1) {
      throw new Error('frozen specification members must be in exact one-based order');
    }
    requireNonEmptyString(member.path, `frozen specification member ${index + 1} path`);
    if (path.isAbsolute(member.path) || path.normalize(member.path) !== member.path) {
      throw new Error('frozen specification member paths must be normalised repository paths');
    }
    requireNonNegativeInteger(
      member.byte_length,
      `frozen specification member ${index + 1} byte length`,
    );
    requireDigest(
      member.payload_digest,
      `frozen specification member ${index + 1} digest`,
    );
    const bytes = exactSourceBytes(
      member.source_bytes_base64,
      `frozen specification member ${index + 1}`,
    );
    if (bytes.length !== member.byte_length
      || crypto.createHash('sha256').update(bytes).digest('hex') !== member.payload_digest) {
      throw new Error('frozen specification member bytes do not match their length and digest');
    }
    return `${member.path}\0${member.byte_length}\0${member.payload_digest}\n`;
  }).join('');
  if (new Set(members.map((member) => member.path)).size !== members.length) {
    throw new Error('frozen specification member paths must be unique');
  }
  return crypto.createHash('sha256')
    .update(Buffer.from(`${SPECIFICATION_ROOT_DOMAIN}\n${records}`, 'utf8'))
    .digest('hex');
}

function requireCanonicalTimestamp(value, label) {
  requireNonEmptyString(value, label);
  const milliseconds = Date.parse(value);
  if (!Number.isFinite(milliseconds) || new Date(milliseconds).toISOString() !== value) {
    throw new TypeError(`${label} must be a canonical UTC timestamp`);
  }
  return milliseconds;
}

function freezeRecord(value) {
  if (!value
    || typeof value !== 'object'
    || Object.isFrozen(value)
    || ArrayBuffer.isView(value)) return value;
  for (const nested of Object.values(value)) freezeRecord(nested);
  return Object.freeze(value);
}

function validateTaskManifest(manifest) {
  requireExactKeys(manifest, TASK_MANIFEST_KEYS, 'review task manifest');
  if (manifest.manifest_version !== TASK_MANIFEST_VERSION) {
    throw new Error(`review task manifest must use ${TASK_MANIFEST_VERSION}`);
  }
  requireToken(manifest.lane_id, 'review lane ID');
  requireDigest(manifest.exact_specification_root, 'exact specification root');

  requireExactKeys(
    manifest.frozen_specification,
    FROZEN_SPECIFICATION_KEYS,
    'frozen specification',
  );
  requireNonEmptyString(manifest.frozen_specification.manifest_id, 'specification manifest ID');
  requireDigest(manifest.frozen_specification.manifest_digest, 'specification manifest digest');
  requireNonNegativeInteger(manifest.frozen_specification.file_count, 'specification file count');
  if (manifest.frozen_specification.file_count === 0) {
    throw new Error('frozen specification must contain at least one file');
  }
  if (manifest.frozen_specification.immutable !== true) {
    throw new Error('frozen specification input must be immutable');
  }
  if (!Array.isArray(manifest.frozen_specification.ordered_members)
    || manifest.frozen_specification.ordered_members.length
      !== manifest.frozen_specification.file_count) {
    throw new Error('frozen specification member inventory must equal its file count');
  }
  const [specificationManifest] = manifest.frozen_specification.ordered_members;
  if (specificationManifest.path !== 'docs/codex-program/specification-manifest.json'
    || specificationManifest.payload_digest
      !== manifest.frozen_specification.manifest_digest
    || specificationRootFromMembers(manifest.frozen_specification.ordered_members)
      !== manifest.exact_specification_root) {
    throw new Error('frozen specification bytes do not derive the exact specification root');
  }

  requireExactKeys(manifest.registered_prompt, REGISTERED_PROMPT_KEYS, 'registered prompt');
  requireToken(manifest.registered_prompt.prompt_id, 'registered prompt ID');
  requireAbsolutePath(manifest.registered_prompt.path, 'registered prompt path');
  requireDigest(manifest.registered_prompt.payload_digest, 'registered prompt digest');
  requireNonNegativeInteger(manifest.registered_prompt.byte_length, 'registered prompt byte length');
  if (manifest.registered_prompt.byte_length === 0) {
    throw new Error('registered prompt must not be empty');
  }
  if (manifest.registered_prompt.immutable !== true) {
    throw new Error('registered prompt input must be immutable');
  }
  if (manifest.registered_prompt.contains_prior_review_conclusions !== false) {
    throw new Error('registered prompt must contain no prior review conclusions');
  }

  requireExactKeys(manifest.output_schema, OUTPUT_SCHEMA_KEYS, 'review output schema');
  requireNonEmptyString(manifest.output_schema.schema_id, 'review output schema ID');
  requireAbsolutePath(manifest.output_schema.path, 'review output schema path');
  requireDigest(manifest.output_schema.payload_digest, 'review output schema digest');
  requireNonNegativeInteger(manifest.output_schema.byte_length, 'review output schema byte length');
  if (manifest.output_schema.byte_length === 0) {
    throw new Error('review output schema must not be empty');
  }
  const outputSchemaBytes = exactSourceBytes(
    manifest.output_schema.source_bytes_base64,
    'review output schema',
  );
  if (outputSchemaBytes.length !== manifest.output_schema.byte_length
    || crypto.createHash('sha256').update(outputSchemaBytes).digest('hex')
      !== manifest.output_schema.payload_digest) {
    throw new Error('review output schema bytes do not match their length and digest');
  }
  if (manifest.output_schema.immutable !== true) {
    throw new Error('review output schema input must be immutable');
  }

  return true;
}

function validateRuntimeContext(context) {
  requireExactKeys(context, RUNTIME_CONTEXT_KEYS, 'fixed review runtime context');
  if (context.context_version !== RUNTIME_CONTEXT_VERSION) {
    throw new Error(`fixed review runtime context must use ${RUNTIME_CONTEXT_VERSION}`);
  }
  requireAbsolutePath(context.review_runtime_binary_path, 'review runtime binary path');
  requireNonEmptyString(context.review_runtime_version, 'review runtime version');
  requireDigest(context.review_runtime_binary_digest, 'review runtime binary digest');
  const controllerRunRoot =
    requireAbsolutePath(context.controller_run_root, 'controller run root');
  const laneRunRoot = requireAbsolutePath(context.lane_run_root, 'lane run root');
  const workingDirectory =
    requireAbsolutePath(context.working_directory, 'review working directory');
  requireNonEmptyString(context.operating_system, 'review operating system');
  requireNonEmptyString(context.architecture, 'review architecture');
  const scratchPaths = [
    requireAbsolutePath(context.home_path, 'fresh HOME path'),
    requireAbsolutePath(context.codex_home_path, 'fresh CODEX_HOME path'),
    requireAbsolutePath(context.tmpdir_path, 'fresh TMPDIR path'),
  ];
  const isolatedPaths = [workingDirectory, ...scratchPaths];
  if (new Set([controllerRunRoot, laneRunRoot, ...isolatedPaths]).size !== 6) {
    throw new Error('review run roots, working directory, HOME, CODEX_HOME and TMPDIR must be distinct');
  }
  if (path.dirname(laneRunRoot) !== controllerRunRoot
    || path.basename(controllerRunRoot).startsWith('g0-cold-review-') !== true
    || path.dirname(workingDirectory) !== laneRunRoot
    || path.basename(workingDirectory) !== 'specification'
    || path.dirname(context.home_path) !== laneRunRoot
    || path.basename(context.home_path) !== 'home'
    || path.dirname(context.codex_home_path) !== laneRunRoot
    || path.basename(context.codex_home_path) !== 'codex-home'
    || path.dirname(context.tmpdir_path) !== laneRunRoot
    || path.basename(context.tmpdir_path) !== 'tmp') {
    throw new Error('review paths must have exact provenance beneath one controller-created run root');
  }
  requireNonEmptyString(context.path_value, 'PATH value');
  requireNonEmptyString(context.lang, 'LANG value');
  requireNonEmptyString(context.lc_all, 'LC_ALL value');
  requireNonEmptyString(context.term, 'TERM value');
  return true;
}

function environmentAssignments(context) {
  return [
    `HOME=${context.home_path}`,
    `CODEX_HOME=${context.codex_home_path}`,
    `TMPDIR=${context.tmpdir_path}`,
    `PATH=${context.path_value}`,
    `LANG=${context.lang}`,
    `LC_ALL=${context.lc_all}`,
    `TERM=${context.term}`,
  ];
}

function codexArguments(manifest) {
  return [
    '-s',
    'read-only',
    '-a',
    'never',
    '--strict-config',
    'exec',
    '--ephemeral',
    '--ignore-user-config',
    '--ignore-rules',
    '--skip-git-repo-check',
    '-m',
    MODEL_IDENTIFIER,
    '-c',
    `model_reasoning_effort="${REASONING_LEVEL}"`,
    '--disable',
    'multi_agent',
    '--disable',
    'multi_agent_v2',
    '--json',
    '--output-schema',
    manifest.output_schema.path,
    '-',
  ];
}

function expectedInvocation(manifest, context) {
  return {
    executable: '/usr/bin/env',
    arguments: [
      '-i',
      ...environmentAssignments(context),
      context.review_runtime_binary_path,
      ...codexArguments(manifest),
    ],
    working_directory: context.working_directory,
    stdin: {
      source: 'REGISTERED_PROMPT_EXACT_BYTES',
      payload_digest: manifest.registered_prompt.payload_digest,
      byte_length: manifest.registered_prompt.byte_length,
    },
    parent_environment: 'EMPTY_ENV_I',
  };
}

function exactInputContext(taskManifest, runtimeContext) {
  return {
    context_version: 'TrustedReviewExactInputContext/V1',
    task_manifest_digest: domainDigest(REVIEW_TASK_MANIFEST_DOMAIN, taskManifest),
    exact_specification_root: taskManifest.exact_specification_root,
    frozen_specification_manifest_digest: taskManifest.frozen_specification.manifest_digest,
    registered_prompt_digest: taskManifest.registered_prompt.payload_digest,
    output_schema_digest: taskManifest.output_schema.payload_digest,
    fixed_runtime_context_digest: domainDigest(REVIEW_RUNTIME_CONTEXT_DOMAIN, runtimeContext),
  };
}

function validateEnvironmentArguments(arguments_) {
  if (!Array.isArray(arguments_) || arguments_[0] !== '-i') {
    throw new Error('review invocation must start with env -i');
  }
  const firstCommandIndex = arguments_.findIndex((value, index) => index > 0 && !value.includes('='));
  if (firstCommandIndex < 0) throw new Error('review invocation is missing the Codex command');
  for (const assignment of arguments_.slice(1, firstCommandIndex)) {
    const separator = assignment.indexOf('=');
    const name = assignment.slice(0, separator);
    if (DENIED_ENVIRONMENT_NAME.test(name)) {
      throw new Error(`review invocation leaks prohibited environment variable ${name}`);
    }
  }
}

function buildTrustedReviewPlan(input) {
  requireExactKeys(input, PLAN_INPUT_KEYS, 'review-controller planning input');
  requireNonEmptyString(input.controller_version, 'controller version');
  requireNonEmptyString(input.controller_run_id, 'controller run ID');
  requireNonEmptyString(input.immutable_task_id, 'immutable task ID');
  requireNonEmptyString(input.nonce, 'controller nonce');
  requireToken(input.controller_key_id, 'controller key ID');
  validateTaskManifest(input.task_manifest);
  validateRuntimeContext(input.runtime_context);

  const taskManifest = freezeRecord(structuredClone(input.task_manifest));
  const runtimeContext = freezeRecord(structuredClone(input.runtime_context));
  const inputContext = exactInputContext(taskManifest, runtimeContext);
  const plan = {
    plan_version: PLAN_VERSION,
    controller_id: CONTROLLER_ID,
    controller_version: input.controller_version,
    controller_run_id: input.controller_run_id,
    immutable_task_id: input.immutable_task_id,
    nonce: input.nonce,
    controller_key_id: input.controller_key_id,
    task_manifest: taskManifest,
    controller_supplied_input_manifest_digest: domainDigest(
      REVIEW_TASK_MANIFEST_DOMAIN,
      taskManifest,
    ),
    fixed_runtime_context: runtimeContext,
    fixed_controller_runtime_context_digest: domainDigest(
      REVIEW_RUNTIME_CONTEXT_DOMAIN,
      runtimeContext,
    ),
    exact_input_context_digest: domainDigest(REVIEW_EXACT_INPUT_CONTEXT_DOMAIN, inputContext),
    reviewer_principal_rule: 'CONTROLLER_RUN_ID/FRESH_CLI_SESSION_ID',
    invocation: expectedInvocation(taskManifest, runtimeContext),
    execution_authority: 'EXTERNAL_PROTECTED_CONTROLLER_ONLY',
  };
  validateTrustedReviewPlan(plan);
  return freezeRecord(plan);
}

function validateTrustedReviewPlan(plan) {
  requireExactKeys(plan, PLAN_KEYS, 'trusted review-controller plan');
  if (plan.plan_version !== PLAN_VERSION) throw new Error(`review plan must use ${PLAN_VERSION}`);
  if (plan.controller_id !== CONTROLLER_ID) throw new Error('review plan has the wrong controller ID');
  requireNonEmptyString(plan.controller_version, 'controller version');
  requireNonEmptyString(plan.controller_run_id, 'controller run ID');
  requireNonEmptyString(plan.immutable_task_id, 'immutable task ID');
  requireNonEmptyString(plan.nonce, 'controller nonce');
  requireToken(plan.controller_key_id, 'controller key ID');
  validateTaskManifest(plan.task_manifest);
  validateRuntimeContext(plan.fixed_runtime_context);
  if (plan.controller_supplied_input_manifest_digest
    !== domainDigest(REVIEW_TASK_MANIFEST_DOMAIN, plan.task_manifest)) {
    throw new Error('review task manifest digest does not match the exact manifest');
  }
  if (plan.fixed_controller_runtime_context_digest
    !== domainDigest(REVIEW_RUNTIME_CONTEXT_DOMAIN, plan.fixed_runtime_context)) {
    throw new Error('fixed runtime context digest does not match the exact context');
  }
  if (plan.exact_input_context_digest
    !== domainDigest(
      REVIEW_EXACT_INPUT_CONTEXT_DOMAIN,
      exactInputContext(plan.task_manifest, plan.fixed_runtime_context),
    )) {
    throw new Error('exact review input-context digest does not match');
  }
  if (plan.reviewer_principal_rule !== 'CONTROLLER_RUN_ID/FRESH_CLI_SESSION_ID') {
    throw new Error('reviewer principal rule must bind the controller run and fresh CLI session');
  }
  requireExactKeys(plan.invocation, INVOCATION_KEYS, 'review invocation');
  requireExactKeys(plan.invocation.stdin, STDIN_KEYS, 'review invocation stdin');
  validateEnvironmentArguments(plan.invocation.arguments);
  const expected = expectedInvocation(plan.task_manifest, plan.fixed_runtime_context);
  if (!canonicalBytes(plan.invocation).equals(canonicalBytes(expected))) {
    throw new Error('review invocation flags, values or order do not match the fixed CLI audit');
  }
  if (plan.execution_authority !== 'EXTERNAL_PROTECTED_CONTROLLER_ONLY') {
    throw new Error('review plan cannot grant local execution authority');
  }
  return true;
}

function buildUnsignedTrustedReviewControllerRecord({ plan, observation }) {
  validateTrustedReviewPlan(plan);
  requireExactKeys(observation, OBSERVATION_KEYS, 'review execution observation');
  requireNonEmptyString(observation.immutable_session_id, 'immutable session ID');
  requireNonEmptyString(observation.immutable_review_id, 'immutable review ID');
  const startedAt = requireCanonicalTimestamp(observation.review_start_time, 'review start time');
  const endedAt = requireCanonicalTimestamp(observation.review_end_time, 'review end time');
  if (endedAt <= startedAt) throw new Error('review end time must be after review start time');
  requireDigest(
    observation.input_context_digest_before_review,
    'input context digest before review',
  );
  requireDigest(
    observation.input_context_digest_after_review,
    'input context digest after review',
  );
  if (observation.input_context_digest_before_review !== plan.exact_input_context_digest
    || observation.input_context_digest_after_review !== plan.exact_input_context_digest) {
    throw new Error('review input changed before, during or after execution');
  }
  if (!observation.review_output
    || typeof observation.review_output !== 'object'
    || Array.isArray(observation.review_output)
    || !['PASS', 'FAIL'].includes(observation.review_output.disposition)) {
    throw new Error('review output must contain terminal disposition PASS or FAIL');
  }
  if (!Array.isArray(observation.reviewer_source_control_identity_set)
    || observation.reviewer_source_control_identity_set.length === 0
    || observation.reviewer_source_control_identity_set.some(
      (identity) => typeof identity !== 'string' || identity.length === 0,
    )
    || new Set(observation.reviewer_source_control_identity_set).size
      !== observation.reviewer_source_control_identity_set.length) {
    throw new Error('reviewer source-control identity set must be complete and unique');
  }
  if (!Array.isArray(observation.reviewer_edit_set)) {
    throw new TypeError('reviewer edit set must be an array');
  }
  if (observation.reviewer_edit_set.length !== 0
    || domainDigest(REVIEWER_EDIT_SET_ROOT_DOMAIN, observation.reviewer_edit_set)
      !== EMPTY_REVIEW_EDIT_SET_ROOT) {
    throw new Error('reviewer edit set must be the exact empty set');
  }
  if (observation.parent_session_state !== 'GENESIS') {
    throw new Error('cold review session must start from GENESIS');
  }
  if (observation.no_earlier_review_conclusions_were_inputs !== true) {
    throw new Error('cold review cannot receive earlier review conclusions');
  }
  if (observation.fresh_cli_session_observed !== true) {
    throw new Error('review must use one fresh CLI session');
  }
  if (observation.read_only_execution_observed !== true) {
    throw new Error('review must be observed as read-only');
  }
  if (observation.controller_direct_execution_observed !== true) {
    throw new Error('protected controller must directly observe the review execution');
  }

  const reviewerPrincipalId = `${plan.controller_run_id}/${observation.immutable_session_id}`;
  const unsignedRecordPayload = {
    schema_version: 'TrustedReviewControllerRecord/V1',
    controller_id: plan.controller_id,
    controller_version: plan.controller_version,
    review_runtime_version: plan.fixed_runtime_context.review_runtime_version,
    review_runtime_binary_digest: plan.fixed_runtime_context.review_runtime_binary_digest,
    fixed_controller_runtime_context_digest: plan.fixed_controller_runtime_context_digest,
    controller_supplied_input_manifest: plan.task_manifest,
    fixed_controller_runtime_context: plan.fixed_runtime_context,
    exact_specification_root: plan.task_manifest.exact_specification_root,
    exact_model_identifier: MODEL_IDENTIFIER,
    reasoning_level: REASONING_LEVEL,
    immutable_task_id: plan.immutable_task_id,
    immutable_session_id: observation.immutable_session_id,
    immutable_review_id: observation.immutable_review_id,
    registered_prompt_id: plan.task_manifest.registered_prompt.prompt_id,
    cold_review_prompt_digest: plan.task_manifest.registered_prompt.payload_digest,
    controller_supplied_input_manifest_digest: plan.controller_supplied_input_manifest_digest,
    exact_input_context_digest: plan.exact_input_context_digest,
    input_context_digest_before_review: observation.input_context_digest_before_review,
    input_context_digest_after_review: observation.input_context_digest_after_review,
    review_output_digest: domainDigest(REVIEW_OUTPUT_DOMAIN, observation.review_output),
    review_start_time: observation.review_start_time,
    review_end_time: observation.review_end_time,
    reviewer_principal_id: reviewerPrincipalId,
    reviewer_source_control_identity_set: [
      ...observation.reviewer_source_control_identity_set,
    ].sort(),
    reviewer_disposition: observation.review_output.disposition,
    reviewer_edit_set_root: EMPTY_REVIEW_EDIT_SET_ROOT,
    parent_session_state: 'GENESIS',
    no_earlier_review_conclusions_were_inputs: true,
    nonce: plan.nonce,
    signature_algorithm: SIGNATURE_ALGORITHM,
    controller_key_id: plan.controller_key_id,
  };
  const signingBytes = signatureBytes({
    domain: CONTROLLER_RECORD_DOMAIN,
    role: CONTROLLER_RECORD_ROLE,
    payload: unsignedRecordPayload,
  });

  return freezeRecord({
    unsigned_record_payload: unsignedRecordPayload,
    signing_frame: {
      frame_version: 'ProgrammeGateSignatureFrame/V1',
      domain: CONTROLLER_RECORD_DOMAIN,
      role: CONTROLLER_RECORD_ROLE,
      payload_digest: domainDigest(CONTROLLER_RECORD_PAYLOAD_DOMAIN, unsignedRecordPayload),
      byte_length: signingBytes.length,
      bytes_base64: signingBytes.toString('base64'),
    },
  });
}

module.exports = {
  CONTROLLER_ID,
  CONTROLLER_RECORD_PAYLOAD_DOMAIN,
  CONTROLLER_RECORD_DOMAIN,
  CONTROLLER_RECORD_ROLE,
  EMPTY_REVIEW_EDIT_SET_ROOT,
  MODEL_IDENTIFIER,
  PLAN_VERSION,
  REASONING_LEVEL,
  REVIEWER_EDIT_SET_ROOT_DOMAIN,
  RUNTIME_CONTEXT_VERSION,
  TASK_MANIFEST_VERSION,
  buildTrustedReviewPlan,
  buildUnsignedTrustedReviewControllerRecord,
  validateTaskManifest,
  validateTrustedReviewPlan,
  specificationRootFromMembers,
};

const { REVIEW_LANES } = require('./registry');

const REVIEW_SET_CONTRACT =
  'five-lane-exact-signed-review-outcomes-recorded/v1';
const BEN_APPROVAL_CONTRACT = 'ben-exact-root-isolated-staging-authorisation/v1';

const REVIEW_MEMBER_SCHEMA_SETS = Object.freeze({
  [REVIEW_SET_CONTRACT]: Object.freeze([
    Object.freeze({
      member_type: 'ColdReviewOutput',
      schema_id: 'ColdReviewOutput/V1',
    }),
    Object.freeze({
      member_type: 'ReviewerIndependenceAttestation',
      schema_id: 'ReviewerIndependenceAttestation/V1',
    }),
    Object.freeze({
      member_type: 'TrustedReviewControllerRecord',
      schema_id: 'TrustedReviewControllerRecord/V1',
    }),
  ]),
  [BEN_APPROVAL_CONTRACT]: Object.freeze([
    Object.freeze({
      member_type: 'BenSpecificationApproval',
      schema_id: 'BenSpecificationApproval/V2',
    }),
    Object.freeze({
      member_type: 'ExactDigestReviewSetAttestation',
      schema_id: 'ExactDigestReviewSetAttestation/V2',
    }),
  ]),
});

function contractForDefinition(definition) {
  const contract = definition && definition.evidence_contract;
  if (!Object.hasOwn(REVIEW_MEMBER_SCHEMA_SETS, contract)) {
    throw new Error(`unsupported review evidence contract: ${contract}`);
  }
  return contract;
}

function member(memberId, memberType, payload) {
  return Object.freeze({
    member_id: memberId,
    member_type: memberType,
    ...(payload === undefined ? {} : { payload }),
  });
}

function expectedReviewMembers() {
  return REVIEW_LANES.flatMap((lane) => [
    member(`controller:${lane.lane_id}`, 'TrustedReviewControllerRecord'),
    member(`output:${lane.lane_id}`, 'ColdReviewOutput'),
    member(`independence:${lane.lane_id}`, 'ReviewerIndependenceAttestation'),
  ]);
}

function expectedApprovalMembers(evidenceObject) {
  return [
    member(`approval:${evidenceObject.approval_evidence_id}`, 'BenSpecificationApproval'),
    member(
      `review-set:${evidenceObject.review_set_evidence_id}`,
      'ExactDigestReviewSetAttestation',
    ),
  ];
}

function enumerateReviewExpectedMembers({ definition, evidenceObject }) {
  const contract = contractForDefinition(definition);
  if (!evidenceObject || typeof evidenceObject !== 'object' || Array.isArray(evidenceObject)) {
    throw new TypeError('review evidence object must be an object');
  }
  return Object.freeze(
    contract === REVIEW_SET_CONTRACT
      ? expectedReviewMembers()
      : expectedApprovalMembers(evidenceObject),
  );
}

function reviewSetMembers(reviewMembers) {
  if (!Array.isArray(reviewMembers)) {
    throw new TypeError('review members must be an array');
  }
  return Object.freeze(reviewMembers.flatMap((entry) => [
    member(
      `controller:${entry.lane_id}`,
      'TrustedReviewControllerRecord',
      entry.controller_record,
    ),
    member(
      `output:${entry.lane_id}`,
      'ColdReviewOutput',
      entry.review_output,
    ),
    member(
      `independence:${entry.lane_id}`,
      'ReviewerIndependenceAttestation',
      entry.independence_attestation,
    ),
  ]));
}

function benApprovalMembers({ approvalEvidenceId, approvalRecord, reviewSetAttestation }) {
  return Object.freeze([
    member(
      `approval:${approvalEvidenceId}`,
      'BenSpecificationApproval',
      approvalRecord,
    ),
    member(
      `review-set:${reviewSetAttestation.review_set_evidence_id}`,
      'ExactDigestReviewSetAttestation',
      reviewSetAttestation,
    ),
  ]);
}

function memberSchemaSetForReview(evidenceContract) {
  const schemaSet = REVIEW_MEMBER_SCHEMA_SETS[evidenceContract];
  if (!schemaSet) {
    throw new Error(`unsupported review evidence contract: ${evidenceContract}`);
  }
  return schemaSet;
}

module.exports = {
  BEN_APPROVAL_CONTRACT,
  REVIEW_MEMBER_SCHEMA_SETS,
  REVIEW_SET_CONTRACT,
  benApprovalMembers,
  enumerateReviewExpectedMembers,
  memberSchemaSetForReview,
  reviewSetMembers,
};

const { domainDigest } = require('./bytes');
const { REVIEW_LANES } = require('./registry');
const { validateSchema } = require('./schema-registry');
const { verifySignature } = require('./signatures');

const CONTROLLER_DOMAIN = 'PROGRAMME_GATE_REVIEW_CONTROLLER_RECORD/V1';
const CONTROLLER_ROLE = 'REVIEW_CONTROLLER';
const INDEPENDENCE_DOMAIN = 'PROGRAMME_GATE_REVIEWER_INDEPENDENCE/V1';
const INDEPENDENCE_ROLE = 'VALIDATOR';
const BEN_APPROVAL_DOMAIN = 'PROGRAMME_GATE_BEN_APPROVAL/V1';
const BEN_APPROVAL_ROLE = 'BEN_APPROVER';
const REVIEW_SET_DOMAIN = 'PROGRAMME_GATE_REVIEW_OUTCOME_SET/V1';
const REVIEW_OUTPUT_DOMAIN = 'PROGRAMME_GATE_REVIEW_OUTPUT/V1';
const BEN_APPROVAL_ID_DOMAIN = 'PROGRAMME_GATE_BEN_APPROVAL_ID/V1';
const GOVERNANCE_DIFF_DOMAIN = 'PROGRAMME_GATE_GOVERNANCE_DIFF/V1';
const REVIEWER_EDIT_SET_ROOT_DOMAIN = 'PROGRAMME_GATE_REVIEWER_EDIT_SET_ROOT/V1';
const AUTHORING_EVENT_INTERSECTION_ROOT_DOMAIN =
  'PROGRAMME_GATE_AUTHORING_EVENT_INTERSECTION_ROOT/V1';
const PRIOR_CONCLUSION_INTERSECTION_ROOT_DOMAIN =
  'PROGRAMME_GATE_PRIOR_CONCLUSION_INTERSECTION_ROOT/V1';
const SOURCE_CONTROL_AUTHORSHIP_EVENT_SET_ROOT_DOMAIN =
  'PROGRAMME_GATE_SOURCE_CONTROL_AUTHORSHIP_EVENT_SET_ROOT/V1';
const EMPTY_REVIEWER_EDIT_SET_ROOT = domainDigest(REVIEWER_EDIT_SET_ROOT_DOMAIN, []);
const EMPTY_AUTHORING_EVENT_INTERSECTION_ROOT =
  domainDigest(AUTHORING_EVENT_INTERSECTION_ROOT_DOMAIN, []);
const EMPTY_PRIOR_CONCLUSION_INTERSECTION_ROOT =
  domainDigest(PRIOR_CONCLUSION_INTERSECTION_ROOT_DOMAIN, []);
const SOL_MODEL = 'gpt-5.6-sol';
const SOL_REASONING = 'high';
const PROHIBITED_ACTIONS = Object.freeze([
  'PRODUCTION_DATA_OR_CORPUS_WRITE',
  'PRODUCTION_REEXTRACTION_OR_BACKFILL',
  'PRODUCTION_OR_RELEASE_IMPORT',
  'RELEASE_ACTIVATION',
  'PRODUCT_FEATURE_ACTIVATION',
  'PRODUCTION_CUTOVER',
]);
const PERMITTED_ACTIONS = Object.freeze([
  'IMPLEMENTATION_PLANNING',
  'ISOLATED_STAGING_SETUP',
  'STAGING_SNAPSHOT_RESTORE_AND_PREVIEW',
  'STAGING_ONLY_CANONICAL_ENGINEERING_BEHIND_DISABLED_PRODUCTION_FLAGS',
]);

const BEN_APPROVAL_KEYS = Object.freeze([
  'schema_version',
  'approved_root',
  'approved_code_commit',
  'review_set_evidence_id',
  'reviewed_root',
  'reviewed_code_commit',
  'review_artifact_sha256',
  'review_artifact_byte_size',
  'full_review_pass_claimed',
  'authorisation_scope',
  'permitted_actions',
  'prohibited_actions',
  'review_findings_disposition',
  'p1_p9_gate_state',
  'governance_diff',
  'github_actor_login',
  'github_actor_id',
  'github_run_id',
  'approval_intent',
  'approver_identity',
  'conditions',
  'approved_at',
  'nonce',
  'signature_algorithm',
  'approver_key_id',
  'signature',
]);

function isRecord(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function exactKeys(value, expected) {
  if (!isRecord(value)) return false;
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length
    && actual.every((key, index) => key === wanted[index]);
}

function unsigned(value, signatureField) {
  const { [signatureField]: signature, ...payload } = value;
  void signature;
  return payload;
}

function open(code, message) {
  return Object.freeze({
    valid: false,
    state: 'OPEN',
    evidence_id: null,
    reason_code: code,
    reason: message,
  });
}

function pass(evidenceId, facts) {
  return Object.freeze({
    valid: true,
    state: 'PASS',
    evidence_id: evidenceId,
    facts: Object.freeze(facts),
    reason_code: null,
    reason: null,
  });
}

function requireDigest(value, label) {
  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value)) {
    throw new Error(`${label} must be a SHA-256 digest`);
  }
}

function verifyController(record, output, lane, authority, expectedRoot, at) {
  validateSchema('TrustedReviewControllerRecord/V1', record);
  validateSchema('ColdReviewOutput/V1', output);
  if (record.exact_specification_root !== expectedRoot
    || record.registered_prompt_id !== lane.registered_prompt_id
    || record.reviewer_disposition !== output.disposition
    || record.review_output_digest !== domainDigest(REVIEW_OUTPUT_DOMAIN, output)
    || record.parent_session_state !== 'GENESIS'
    || record.no_earlier_review_conclusions_were_inputs !== true
    || record.input_context_digest_before_review !== record.exact_input_context_digest
    || record.input_context_digest_after_review !== record.exact_input_context_digest
    || record.reviewer_edit_set_root !== EMPTY_REVIEWER_EDIT_SET_ROOT) {
    throw new Error('controller record does not prove an exact cold-review outcome');
  }
  if (!authority.allowed_controllers.some((entry) => (
    entry.controller_id === record.controller_id
    && entry.controller_version === record.controller_version
  ))) throw new Error('controller identity or version is not allowlisted');
  if (!authority.allowed_runtimes.some((entry) => (
    entry.review_runtime_version === record.review_runtime_version
    && entry.review_runtime_binary_digest === record.review_runtime_binary_digest
    && entry.fixed_controller_runtime_context_digest
      === record.fixed_controller_runtime_context_digest
  ))) throw new Error('review runtime or fixed context is not allowlisted');
  if (!authority.allowed_prompts.some((entry) => (
    entry.lane_id === lane.lane_id
    && entry.registered_prompt_id === record.registered_prompt_id
    && entry.cold_review_prompt_digest === record.cold_review_prompt_digest
  ))) throw new Error('review prompt is not allowlisted for the lane');

  const legalEligible = (
    authority.fable_model_identifiers.includes(record.exact_model_identifier)
    && record.reasoning_level === 'provider_default'
  )
    || (
      record.exact_model_identifier === SOL_MODEL
      && record.reasoning_level === SOL_REASONING
    );
  if (lane.lane_id === 'LEGAL_SEMANTIC' && !legalEligible) {
    throw new Error('legal-semantic reviewer is not eligible');
  }
  if (lane.lane_id !== 'LEGAL_SEMANTIC'
    && !authority.other_lane_model_identifiers.includes(record.exact_model_identifier)) {
    throw new Error('reviewer model is not eligible for this lane');
  }

  verifySignature({
    keyRegistry: authority.key_registry,
    keyId: record.controller_key_id,
    role: CONTROLLER_ROLE,
    domain: CONTROLLER_DOMAIN,
    payload: unsigned(record, 'controller_signature'),
    signature: record.controller_signature,
    at,
  });
}

function verifyIndependence(attestation, record, authority, expectedCodeCommit, at) {
  validateSchema('ReviewerIndependenceAttestation/V1', attestation);
  const reviewerIdentities = new Set(record.reviewer_source_control_identity_set);
  const authoringIntersection = attestation.source_control_authorship_events.filter(
    (event) => event.identity_set.some((identity) => reviewerIdentities.has(identity)),
  );
  const priorIntersection = attestation.prior_conclusion_input_set.filter(
    (conclusion) => reviewerIdentities.has(conclusion),
  );
  if (attestation.reviewer_principal_id !== record.reviewer_principal_id
    || attestation.immutable_session_id !== record.immutable_session_id
    || attestation.session_parent_or_genesis !== 'GENESIS'
    || attestation.exact_input_context_digest !== record.exact_input_context_digest
    || attestation.reviewed_code_commit !== expectedCodeCommit
    || attestation.source_control_history_scope
      !== 'REVIEWED_COMMIT_ANCESTRY_FROM_REPOSITORY_GENESIS'
    || attestation.source_control_authorship_event_set_root
      !== domainDigest(
        SOURCE_CONTROL_AUTHORSHIP_EVENT_SET_ROOT_DOMAIN,
        attestation.source_control_authorship_events,
      )
    || attestation.authoring_event_intersection_root
      !== domainDigest(AUTHORING_EVENT_INTERSECTION_ROOT_DOMAIN, authoringIntersection)
    || authoringIntersection.length !== 0
    || attestation.prior_conclusion_intersection_root
      !== domainDigest(PRIOR_CONCLUSION_INTERSECTION_ROOT_DOMAIN, priorIntersection)
    || priorIntersection.length !== 0
    || attestation.reviewer_edit_set_root !== EMPTY_REVIEWER_EDIT_SET_ROOT) {
    throw new Error('review independence was not recomputed from complete evidence');
  }
  if (!authority.allowed_independence_validators.some((entry) => (
    entry.validator_executable_digest === attestation.validator_executable_digest
    && entry.validator_configuration_digest === attestation.validator_configuration_digest
    && entry.validator_key_id === attestation.validator_key_id
  ))) throw new Error('independence validator is not allowlisted');

  verifySignature({
    keyRegistry: authority.key_registry,
    keyId: attestation.validator_key_id,
    role: INDEPENDENCE_ROLE,
    domain: INDEPENDENCE_DOMAIN,
    payload: unsigned(attestation, 'signature'),
    signature: attestation.signature,
    at,
  });
}

function verifyReviewSetEvidence(input) {
  try {
    if (!isRecord(input)
      || !Array.isArray(input.members)
      || !isRecord(input.authority)
      || typeof input.at === 'undefined') {
      throw new Error('review-set input is incomplete');
    }
    requireDigest(input.expected_specification_root, 'expected specification root');
    requireDigest(input.review_artifact_sha256, 'review artefact SHA-256');
    if (!Number.isInteger(input.review_artifact_byte_size)
      || input.review_artifact_byte_size < 1) {
      throw new Error('review artefact byte size must be a positive integer');
    }
    if (typeof input.expected_code_commit !== 'string'
      || !/^[a-f0-9]{40}$/.test(input.expected_code_commit)) {
      throw new Error('expected code commit must be a Git commit ID');
    }
    const expectedLanes = REVIEW_LANES.map((lane) => lane.lane_id);
    if (input.members.length !== expectedLanes.length) {
      throw new Error('review set must contain exactly five lanes');
    }
    const laneIds = input.members.map((member) => member && member.lane_id);
    if (new Set(laneIds).size !== expectedLanes.length
      || !expectedLanes.every((laneId) => laneIds.includes(laneId))) {
      throw new Error('review set has missing or duplicate lanes');
    }
    const nonces = new Set();
    const principals = new Set();
    const ordered = REVIEW_LANES.map((lane) => {
      const member = input.members.find((candidate) => candidate.lane_id === lane.lane_id);
      if (!exactKeys(
        member,
        ['lane_id', 'controller_record', 'independence_attestation', 'review_output'],
      )) {
        throw new Error('review lane member has an open or incomplete shape');
      }
      verifyController(
        member.controller_record,
        member.review_output,
        lane,
        input.authority,
        input.expected_specification_root,
        input.at,
      );
      verifyIndependence(
        member.independence_attestation,
        member.controller_record,
        input.authority,
        input.expected_code_commit,
        input.at,
      );
      if (nonces.has(member.controller_record.nonce)
        || principals.has(member.controller_record.reviewer_principal_id)) {
        throw new Error('review nonce and principal must be unique per lane');
      }
      nonces.add(member.controller_record.nonce);
      principals.add(member.controller_record.reviewer_principal_id);
      return member;
    });
    const evidenceId = domainDigest(REVIEW_SET_DOMAIN, {
      reviewed_code_commit: input.expected_code_commit,
      reviewed_root: input.expected_specification_root,
      review_artifact_sha256: input.review_artifact_sha256,
      review_artifact_byte_size: input.review_artifact_byte_size,
      ordered_members: ordered,
    });
    const laneOutcomes = ordered.map((member) => Object.freeze({
      lane_id: member.lane_id,
      disposition: member.review_output.disposition,
      review_output_digest: member.controller_record.review_output_digest,
      blocking_finding_count: member.review_output.findings.filter(
        (finding) => finding.severity === 'BLOCKING',
      ).length,
    }));
    return pass(evidenceId, {
      reviewed_root: input.expected_specification_root,
      reviewed_code_commit: input.expected_code_commit,
      review_artifact_sha256: input.review_artifact_sha256,
      review_artifact_byte_size: input.review_artifact_byte_size,
      lane_ids: Object.freeze(expectedLanes),
      lane_outcomes: Object.freeze(laneOutcomes),
      full_review_disposition: laneOutcomes.every(
        (outcome) => outcome.disposition === 'PASS',
      ) ? 'PASS' : 'FAIL',
      full_review_pass_claimed: false,
      legal_reviewer_eligible: true,
      independence_recomputed: true,
      root_before: input.expected_specification_root,
      root_after: input.expected_specification_root,
    });
  } catch (error) {
    return open('REVIEW_SET_NOT_VERIFIED', error.message);
  }
}

function validateBenApprovalRecord(record) {
  validateSchema('BenSpecificationApproval/V2', record);
  if (!exactKeys(record, BEN_APPROVAL_KEYS)
    || record.schema_version !== 'BenSpecificationApproval/V2'
    || record.approver_identity !== 'BEN_GOODCHILD'
    || record.full_review_pass_claimed !== false
    || record.authorisation_scope !== 'ISOLATED_STAGING_CANONICAL_IMPLEMENTATION'
    || JSON.stringify(record.permitted_actions) !== JSON.stringify(PERMITTED_ACTIONS)
    || !Array.isArray(record.prohibited_actions)
    || record.prohibited_actions.length !== PROHIBITED_ACTIONS.length
    || !PROHIBITED_ACTIONS.every((action) => record.prohibited_actions.includes(action))
    || record.review_findings_disposition !== 'ACKNOWLEDGED_NOT_RESOLVED_OR_WAIVED'
    || record.p1_p9_gate_state !== 'OPEN'
    || record.governance_diff?.basis_code_commit !== record.reviewed_code_commit
    || record.governance_diff?.authorised_code_commit !== record.approved_code_commit
    || !Array.isArray(record.governance_diff?.changed_paths)
    || record.governance_diff.changed_paths.length === 0
    || !Array.isArray(record.governance_diff?.unexpected_paths)
    || record.governance_diff.unexpected_paths.length !== 0
    || record.github_actor_login !== 'CodeNameHash'
    || record.github_actor_id !== '264183176'
    || typeof record.github_run_id !== 'string'
    || record.github_run_id.length === 0
    || record.approval_intent
      !== 'AUTHORISE_ISOLATED_STAGING_CANONICAL_IMPLEMENTATION'
    || record.signature_algorithm !== 'Ed25519'
    || !Array.isArray(record.conditions)
    || typeof record.approved_at !== 'string'
    || !Number.isFinite(Date.parse(record.approved_at))
    || typeof record.nonce !== 'string'
    || record.nonce.length === 0
    || typeof record.approver_key_id !== 'string'
    || record.approver_key_id.length === 0
    || typeof record.signature !== 'string'
    || record.signature.length === 0) {
    throw new Error('Ben approval record is not a closed signed record');
  }
  requireDigest(record.approved_root, 'approved root');
  requireDigest(record.review_set_evidence_id, 'review-set evidence ID');
  requireDigest(record.reviewed_root, 'reviewed root');
  requireDigest(record.review_artifact_sha256, 'review artefact SHA-256');
  requireDigest(record.governance_diff.allowed_path_set_digest, 'allowed path-set digest');
  requireDigest(record.governance_diff.patch_digest, 'governance patch digest');
}

function verifyBenApprovalEvidence(input) {
  try {
    if (!isRecord(input) || !isRecord(input.record) || !isRecord(input.authority)) {
      throw new Error('Ben approval input is incomplete');
    }
    validateBenApprovalRecord(input.record);
    if (input.record.approved_root !== input.expected_specification_root
      || input.record.approved_code_commit !== input.expected_code_commit
      || input.record.review_set_evidence_id !== input.review_set_evidence_id
      || input.record.reviewed_root !== input.reviewed_root
      || input.record.reviewed_code_commit !== input.reviewed_code_commit
      || input.record.conditions.length !== 0) {
      throw new Error('Ben approval is conditional or bound to another root or commit');
    }
    verifySignature({
      keyRegistry: input.authority.key_registry,
      keyId: input.record.approver_key_id,
      role: BEN_APPROVAL_ROLE,
      domain: BEN_APPROVAL_DOMAIN,
      payload: unsigned(input.record, 'signature'),
      signature: input.record.signature,
      at: input.at,
    });
    const evidenceId = domainDigest(BEN_APPROVAL_ID_DOMAIN, input.record);
    return pass(evidenceId, {
      approved_root: input.record.approved_root,
      approved_code_commit: input.record.approved_code_commit,
      review_set_evidence_id: input.record.review_set_evidence_id,
      reviewed_root: input.record.reviewed_root,
      reviewed_code_commit: input.record.reviewed_code_commit,
      review_artifact_sha256: input.record.review_artifact_sha256,
      review_artifact_byte_size: input.record.review_artifact_byte_size,
      full_review_pass_claimed: false,
      authorisation_scope: input.record.authorisation_scope,
      permitted_actions: Object.freeze([...input.record.permitted_actions]),
      prohibited_actions: Object.freeze([...input.record.prohibited_actions]),
      review_findings_disposition: input.record.review_findings_disposition,
      p1_p9_gate_state: input.record.p1_p9_gate_state,
      governance_diff_digest: domainDigest(
        GOVERNANCE_DIFF_DOMAIN,
        input.record.governance_diff,
      ),
      github_actor_login: input.record.github_actor_login,
      github_actor_id: input.record.github_actor_id,
      github_run_id: input.record.github_run_id,
      approval_intent: input.record.approval_intent,
      identity_and_signature_verified: true,
      scope_bounded: true,
    });
  } catch (error) {
    return open('BEN_APPROVAL_NOT_VERIFIED', error.message);
  }
}

function projectReviewSetAttestation(verification) {
  if (!verification
    || verification.valid !== true
    || verification.state !== 'PASS'
    || !verification.facts) {
    throw new Error('a passing review-set verification is required');
  }
  const attestation = {
    review_set_evidence_id: verification.evidence_id,
    reviewed_root: verification.facts.reviewed_root,
    reviewed_code_commit: verification.facts.reviewed_code_commit,
    review_artifact_sha256: verification.facts.review_artifact_sha256,
    review_artifact_byte_size: verification.facts.review_artifact_byte_size,
    lane_outcomes: verification.facts.lane_outcomes.map((outcome) => ({ ...outcome })),
    full_review_disposition: verification.facts.full_review_disposition,
    full_review_pass_claimed: false,
  };
  validateSchema('ExactDigestReviewSetAttestation/V2', attestation);
  return Object.freeze(attestation);
}

function projectBenApprovalEvidence(verification, record) {
  if (!verification
    || verification.valid !== true
    || verification.state !== 'PASS'
    || !verification.facts
    || !record) {
    throw new Error('a passing Ben approval verification and record are required');
  }
  const evidence = {
    approval_evidence_id: verification.evidence_id,
    approved_root: verification.facts.approved_root,
    approved_code_commit: verification.facts.approved_code_commit,
    review_set_evidence_id: verification.facts.review_set_evidence_id,
    reviewed_root: verification.facts.reviewed_root,
    reviewed_code_commit: verification.facts.reviewed_code_commit,
    review_artifact_sha256: verification.facts.review_artifact_sha256,
    review_artifact_byte_size: verification.facts.review_artifact_byte_size,
    full_review_pass_claimed: false,
    authorisation_scope: verification.facts.authorisation_scope,
    permitted_actions: [...verification.facts.permitted_actions],
    prohibited_actions: [...verification.facts.prohibited_actions],
    review_findings_disposition: verification.facts.review_findings_disposition,
    p1_p9_gate_state: verification.facts.p1_p9_gate_state,
    governance_diff_digest: verification.facts.governance_diff_digest,
    github_actor_login: verification.facts.github_actor_login,
    github_actor_id: verification.facts.github_actor_id,
    github_run_id: verification.facts.github_run_id,
    approval_intent: verification.facts.approval_intent,
    conditions: [...record.conditions],
  };
  validateSchema('BenSpecificationApprovalEvidence/V2', evidence);
  return Object.freeze(evidence);
}

