}) {
  validateSchema(definition.evidence_object_json_schema_id, candidate.evidence_object);
  const { evidence_subject: subject, evidence_object: evidenceObject } = candidate;
  if (subject.gate_id !== gate.id
    || subject.code_commit !== bundle.code_commit
    || subject.environment !== bundle.environment
    || subject.observed_at !== bundle.observed_at
    || subject.attestation_source_digest !== bundle.attestation_source_digest
    || evidenceObject.gate_id !== gate.id
    || evidenceObject.code_commit !== bundle.code_commit
    || evidenceObject.environment !== bundle.environment
    || evidenceObject.observed_at !== bundle.observed_at
    || evidenceObject.attestation_source_digest !== bundle.attestation_source_digest) {
    throw new Error('security evidence subject or object has drifted from readiness');
  }
  const expectedSchemaSet = memberSchemaSetForSecurityDisposition(gate.evidence_contract);
  if (domainDigest(MEMBER_SCHEMA_SET_DOMAIN, candidate.member_schema_set)
      !== definition.immutable_member_json_schema_set_digest
    || domainDigest(MEMBER_SCHEMA_SET_DOMAIN, expectedSchemaSet)
      !== definition.immutable_member_json_schema_set_digest) {
    throw new Error('security evidence member schema set has drifted');
  }
  for (const member of orderedMembers) {
    const binding = expectedSchemaSet.find((entry) => entry.member_type === member.member_type);
    if (!binding) throw new Error(`unbound security member type ${member.member_type}`);
    validateSchema(binding.schema_id, member.payload);
  }
  if (orderedTests.length !== 1
    || orderedTests[0].test_id !== 'GATE-01'
    || orderedTests[0].exit_code !== 0
    || orderedTests[0].code_commit !== bundle.code_commit
    || orderedTests[0].environment !== bundle.environment
    || Date.parse(orderedTests[0].completed_at) > Date.parse(bundle.observed_at)) {
    throw new Error('security evidence does not bind one passing GATE-01 execution');
  }
  validateSchema('ProgrammeGateTestExecutionRecord/V1', orderedTests[0]);
  const recomputedClaims = evaluateAcceptanceClaims({
    gate_id: gate.id,
    evidence: evidenceObject,
    context: {
      specificationRoot: bundle.specification_root,
      codeCommit: bundle.code_commit,
      environment: bundle.environment,
      expectedSpecificationRoot: bundle.specification_root,
      expectedCodeCommit: bundle.code_commit,
      expectedEnvironment: bundle.environment,
      observed_at: bundle.observed_at,
      clock: { now: () => authority.verificationTime },
    },
  });
  if (domainDigest('PROGRAMME_GATE_ACCEPTANCE_CLAIMS/V1', recomputedClaims)
      !== domainDigest('PROGRAMME_GATE_ACCEPTANCE_CLAIMS/V1', candidate.exact_acceptance_claims)
    || recomputedClaims.some((claim) => claim.typed_value !== true)) {
    throw new Error('security acceptance claims are not exact passing measurements');
  }
}

function buildSecurityDispositionSigningRequest(input) {
  requireExactKeys(
    input,
    ['authority', 'bundle', 'candidate'],
    'security-disposition signing request',
  );
  const authority = requireAuthority(input.authority);
  const { bundle, candidate } = input;
  if (bundle.readiness_type !== 'ProgrammeGateSecurityDispositionReadiness/V1'
    || bundle.readiness_state !== 'READY_FOR_SIGNATURE'
    || bundle.formal_gate_state !== 'OPEN'
    || bundle.private_key_used !== false
    || bundle.status_publication_attempted !== false
    || candidate.readiness_state !== 'READY_FOR_SIGNATURE'
    || candidate.formal_gate_state !== 'OPEN'
    || candidate.signature !== null) {
    throw new Error('only exact unsigned OPEN security readiness may be signed');
  }
  const gate = gateForCandidate(candidate);
  const definition = definitionFor(bundle, candidate);
  const expectedMembers = enumerateSecurityDispositionExpectedMembers({
    definition,
    evidenceObject: candidate.evidence_object,
  });
  const orderedMembers = enumerateClosedMembers({
    expectedMembers,
    members: candidate.members,
  });
  const orderedTests = [...candidate.test_results].sort(
    (left, right) => compareUtf8(left.test_id, right.test_id),
  );
  validateCandidate({
    authority,
    bundle,
    candidate,
    gate,
    definition,
    orderedMembers,
    orderedTests,
  });
  const unsignedEnvelope = {
    schema_version: 'ProgrammeGateEvidenceEnvelope/V2',
    gate_id: gate.id,
    evidence_contract: gate.evidence_contract,
    acceptance_definition_id: definition.definition_id,
    acceptance_definition_digest: definition.definition_digest,
    specification_root: bundle.specification_root,
    code_commit: bundle.code_commit,
    environment: bundle.environment,
    evidence_subject_type: definition.evidence_subject_type,
    evidence_subject_id: domainDigest(
      EVIDENCE_SUBJECT_ID_DOMAIN,
      subjectIdentity(
        candidate.evidence_subject,
        definition.evidence_subject_identity_fields,
      ),
    ),
    evidence_subject_payload_digest: domainDigest(
      EVIDENCE_SUBJECT_PAYLOAD_DOMAIN,
      candidate.evidence_subject,
    ),
    required_evidence_object_type: gate.required_evidence_object_type,
    required_evidence_object_payload_digest: domainDigest(
      EVIDENCE_OBJECT_PAYLOAD_DOMAIN,
      candidate.evidence_object,
    ),
    exact_acceptance_claims: candidate.exact_acceptance_claims,
    immutable_member_root: domainDigest(IMMUTABLE_MEMBER_ROOT_DOMAIN, orderedMembers),
    test_result_root: domainDigest(TEST_RESULT_ROOT_DOMAIN, orderedTests),
    validator_executable_digest: authority.validatorExecutableDigest,
    validator_configuration_digest: authority.validatorConfigurationDigest,
    validator_key_id: authority.validatorKeyId,
    terminal_state: 'PASS',
    signature_algorithm: 'Ed25519',
  };
  validateSchema('ProgrammeGateEvidenceEnvelope/V2', {
    ...unsignedEnvelope,
    signature: 'AA==',
  });
  const signingFrame = signatureBytes({
    domain: EVIDENCE_SIGNATURE_DOMAIN,
    role: EVIDENCE_SIGNATURE_ROLE,
    payload: unsignedEnvelope,
  });
  return deepFreeze({
    request_type: 'ProgrammeGateSecurityDispositionSigningRequest/V1',
    gate_id: gate.id,
    unsigned_envelope: unsignedEnvelope,
    signing_domain: EVIDENCE_SIGNATURE_DOMAIN,
    signing_role: EVIDENCE_SIGNATURE_ROLE,
    signing_frame_sha256: crypto.createHash('sha256').update(signingFrame).digest('hex'),
    signing_frame_base64: signingFrame.toString('base64'),
    readiness_state: 'READY_FOR_EXTERNAL_SIGNATURE',
    formal_gate_state: 'OPEN',
    private_key_used: false,
    signature: null,
  });
}

function matchingContracts(bundle) {
  const contracts = createSecurityDispositionContractBundle({
    specificationRoot: bundle.specification_root,
  });
  if (domainDigest(CONTRACT_DEFINITION_SET_DOMAIN, bundle.acceptance_definitions)
      !== domainDigest(CONTRACT_DEFINITION_SET_DOMAIN, contracts.definitions)
    || domainDigest(EXECUTABLE_BINDING_SET_DOMAIN, bundle.executable_bindings)
      !== domainDigest(EXECUTABLE_BINDING_SET_DOMAIN, contracts.executable_bindings)) {
    throw new Error('security readiness contracts have drifted');
  }
  return contracts;
}

function openValidation(gateId, reasonCode) {
  return Object.freeze({
    valid: false,
    state: 'OPEN',
    gate_id: gateId,
    evidence_envelope_id: null,
    evidence_payload_digest: null,
    reason_code: reasonCode,
    reason: 'Signed security evidence did not match exact readiness.',
  });
}

function preflightSecurityDispositionSignature(input) {
  requireExactKeys(input, [
    'authority',
    'bundle',
    'candidate',
    'signature',
    'signingRequest',
  ], 'security-disposition signed preflight');
  const authority = requireAuthority(input.authority);
  const gateId = input.candidate && input.candidate.gate_id;
  let expectedRequest;
  let contracts;
  try {
    expectedRequest = buildSecurityDispositionSigningRequest({
      authority,
      bundle: input.bundle,
      candidate: input.candidate,
    });
    if (domainDigest(SIGNING_REQUEST_DOMAIN, input.signingRequest)
      !== domainDigest(SIGNING_REQUEST_DOMAIN, expectedRequest)) {
      throw new Error('signing request mismatch');
    }
    contracts = matchingContracts(input.bundle);
  } catch {
    return deepFreeze({
      preflight_type: 'ProgrammeGateSecurityDispositionSignedPreflight/V1',
      gate_id: gateId || null,
      evidence_validation: openValidation(gateId || null, 'SIGNING_REQUEST_MISMATCH'),
      signed_envelope: null,
      evidence_validation_state: 'OPEN',
      formal_gate_state: 'OPEN',
      private_key_used: false,
      status_publication_attempted: false,
    });
  }

  const signedEnvelope = {
    ...expectedRequest.unsigned_envelope,
    signature: input.signature,
  };
  const validateEvidence = createProgrammeGateEvidenceValidator({
    domainDigest,
    validateSchema,
    schemaFor,
    knownSchemaIds: SCHEMA_IDS,
    acceptanceDescriptorForContract,
    acceptanceDefinitions: contracts.definitions,
    enumerateClosedMembers,
    enumerateExpectedMembers: enumerateSecurityDispositionExpectedMembers,
    evaluateAcceptanceClaims,
    predicateRegistry: ACCEPTANCE_PREDICATES,
    verifySignature,
    validatorConfiguration: VALIDATOR_CONFIGURATION,
    allowedValidatorExecutableDigests: [authority.validatorExecutableDigest],
    executableBindings: contracts.executable_bindings,
    keyRegistry: authority.keyRegistry,
  });
  const gate = gateForCandidate(input.candidate);
  const validation = validateEvidence({
    gate,
    envelope: signedEnvelope,
    evidenceSubject: input.candidate.evidence_subject,
    evidenceObject: input.candidate.evidence_object,
    members: input.candidate.members,
    memberSchemaSet: input.candidate.member_schema_set,
    testResults: input.candidate.test_results,
    expectedSpecificationRoot: input.bundle.specification_root,
    expectedFrozenContractPairDigest: null,
    expectedCodeCommit: input.bundle.code_commit,
    expectedEnvironment: input.bundle.environment,
    clock: { now: () => authority.verificationTime },
  });
  return deepFreeze({
    preflight_type: 'ProgrammeGateSecurityDispositionSignedPreflight/V1',
    gate_id: gate.id,
    evidence_validation: validation,
    signed_envelope: validation.valid === true ? signedEnvelope : null,
    evidence_validation_state: validation.state,
    formal_gate_state: 'OPEN',
    private_key_used: false,
    status_publication_attempted: false,
  });
}

module.exports = {
  SIGNING_REQUEST_DOMAIN,
  buildSecurityDispositionSigningRequest,
  createSecurityDispositionSigningAuthority,
  preflightSecurityDispositionSignature,
};

const crypto = require('node:crypto');
const { signatureBytes } = require('./bytes');
const { validateSchema } = require('./schema-registry');

const SIGNATURE_ALGORITHM = 'Ed25519';
const SUPPORTED_KEY_TYPE = 'ed25519';
const TRUSTED_KEY_FIELDS = Object.freeze([
  'algorithm',
  'key_id',
  'permitted_domains',
  'permitted_roles',
  'public_key_pem',
  'revoked_at',
  'valid_from',
  'valid_until',
]);

function asEpochMilliseconds(value, label) {
  if (value instanceof Date) {
    const milliseconds = value.getTime();
    if (Number.isFinite(milliseconds)) return milliseconds;
  }
  if (typeof value === 'string') {
    const milliseconds = Date.parse(value);
    if (Number.isFinite(milliseconds)) return milliseconds;
  }
  if (Number.isFinite(value)) return value;
  throw new TypeError(`${label} must be a valid time`);
}

function keyForVerification({
  keyRegistry,
  keyId,
  role,
  domain,
  at,
}) {
  if (!keyRegistry || !Array.isArray(keyRegistry.keys)) {
    throw new TypeError('trusted public-key registry is invalid');
  }
  validateSchema('TrustedProgrammeGatePublicKeys/V1', keyRegistry);
  if (keyRegistry.registry_state !== 'ACTIVE') {
    throw new Error('trusted public-key registry is not active');
  }
  const matches = keyRegistry.keys.filter((entry) => entry.key_id === keyId);
  if (matches.length !== 1) throw new Error(`untrusted or ambiguous key ID: ${keyId}`);

  const key = matches[0];
  const actualFields = Object.keys(key).sort();
  if (actualFields.length !== TRUSTED_KEY_FIELDS.length
    || actualFields.some((field, index) => field !== TRUSTED_KEY_FIELDS[index])) {
    throw new Error(`key ${keyId} does not match the closed trusted-key record`);
  }
  if (key.algorithm !== SIGNATURE_ALGORITHM) {
    throw new Error(`key ${keyId} does not permit ${SIGNATURE_ALGORITHM}`);
  }
  if (!Array.isArray(key.permitted_roles) || !key.permitted_roles.includes(role)) {
    throw new Error(`key ${keyId} does not permit role ${role}`);
  }
  if (!Array.isArray(key.permitted_domains) || !key.permitted_domains.includes(domain)) {
    throw new Error(`key ${keyId} does not permit domain ${domain}`);
  }

  const verificationTime = asEpochMilliseconds(at, 'verification time');
  const validFrom = asEpochMilliseconds(key.valid_from, 'key valid_from');
  const validUntil = asEpochMilliseconds(key.valid_until, 'key valid_until');
  if (validFrom >= validUntil) throw new Error(`key ${keyId} has an invalid validity interval`);
  if (key.revoked_at !== null
    && verificationTime >= asEpochMilliseconds(key.revoked_at, 'key revoked_at')) {
    throw new Error(`key ${keyId} is revoked`);
  }
  if (verificationTime < validFrom) {
    throw new Error(`key ${keyId} is not yet valid`);
  }
  if (verificationTime >= validUntil) {
    throw new Error(`key ${keyId} is expired`);
  }

  const publicKey = crypto.createPublicKey(key.public_key_pem);
  if (publicKey.asymmetricKeyType !== SUPPORTED_KEY_TYPE) {
    throw new Error(`key ${keyId} must be an Ed25519 public key`);
  }
  return publicKey;
}

function decodeSignature(value) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError('signature must be non-empty base64');
  }
  const signature = Buffer.from(value, 'base64');
  if (signature.length === 0 || signature.toString('base64') !== value) {
    throw new TypeError('signature must use canonical base64');
  }
  return signature;
}

function verifySignature({
  keyRegistry,
  keyId,
  role,
  domain,
  payload,
  signature,
  at = Date.now(),
}) {
  const publicKey = keyForVerification({
    keyRegistry,
    keyId,
    role,
    domain,
    at,
  });
  const verified = crypto.verify(
    null,
    signatureBytes({ domain, role, payload }),
    publicKey,
    decodeSignature(signature),
  );
  if (!verified) throw new Error('programme-gate signature verification failed');
  return true;
}

module.exports = {
  SIGNATURE_ALGORITHM,
  verifySignature,
};

const {
  BOOTSTRAP_NONCE,
  requireGoverningRegistryAuthority,
} = require('./governing-registry');
const {
  EVIDENCE_ENVELOPE_ID_DOMAIN,
  EVIDENCE_PAYLOAD_DOMAIN,
} = require('./validator');

const DIGEST_PATTERN = /^[a-f0-9]{64}$/;
const COMMIT_PATTERN = /^[a-f0-9]{40}$/;
const authorityBrands = new WeakSet();

function requireExactKeys(value, allowedKeys, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`${label} must be an object`);
  }
  const keys = Object.keys(value);
  const extras = keys.filter((key) => !allowedKeys.includes(key));
  const missing = allowedKeys.filter((key) => !keys.includes(key));
  if (extras.length > 0) throw new Error(`${label} has unsupported fields: ${extras.join(', ')}`);
  if (missing.length > 0) throw new Error(`${label} is missing fields: ${missing.join(', ')}`);
}

function requireFunction(value, label) {
  if (typeof value !== 'function') throw new TypeError(`${label} must be a function`);
  return value;
}

function requireDigest(value, label) {
  if (!DIGEST_PATTERN.test(value)) throw new TypeError(`${label} must be a SHA-256 digest`);
  return value;
}

function requireCommit(value, label) {
  if (!COMMIT_PATTERN.test(value)) throw new TypeError(`${label} must be a Git commit ID`);
  return value;
}

function createProgrammeStatusAuthority(dependencies) {
  requireExactKeys(dependencies, [
    'governingRegistryAuthority',
    'domainDigest',
    'validateEvidence',
    'evidencePayloadForDigest',
    'validateStatusSchema',
    'verifyStatusSignature',
    'validatorExecutableDigest',
    'validatorConfigurationDigest',
    'validatorKeyId',
    'bootstrapState',
    'terminalPairState',
  ], 'programme status authority dependencies');

  const registry = requireGoverningRegistryAuthority(dependencies.governingRegistryAuthority);
  const authority = Object.freeze({
    registry,
    domainDigest: requireFunction(dependencies.domainDigest, 'domainDigest'),
    validateEvidence: requireFunction(dependencies.validateEvidence, 'validateEvidence'),
    evidencePayloadForDigest: requireFunction(
      dependencies.evidencePayloadForDigest,
      'evidencePayloadForDigest',
    ),
    validateStatusSchema: requireFunction(
      dependencies.validateStatusSchema,
      'validateStatusSchema',
    ),
    verifyStatusSignature: requireFunction(
      dependencies.verifyStatusSignature,
      'verifyStatusSignature',
    ),
    validatorExecutableDigest: requireDigest(
      dependencies.validatorExecutableDigest,
      'validator executable digest',
    ),
    validatorConfigurationDigest: requireDigest(
      dependencies.validatorConfigurationDigest,
      'validator configuration digest',
    ),
    validatorKeyId: dependencies.validatorKeyId,
    bootstrapState: dependencies.bootstrapState,
    terminalPairState: dependencies.terminalPairState,
  });
  if (typeof authority.validatorKeyId !== 'string' || authority.validatorKeyId.length === 0) {
    throw new TypeError('validator key ID must be non-empty');
  }
  if (!['AVAILABLE', 'CONSUMED'].includes(authority.bootstrapState)) {
    throw new Error('bootstrap state must be AVAILABLE or CONSUMED');
  }
  if (!['UNVALIDATED', 'VALIDATED'].includes(authority.terminalPairState)) {
    throw new Error('terminal-pair state must be UNVALIDATED or VALIDATED');
  }
  authorityBrands.add(authority);
  return authority;
}

function requireProgrammeStatusAuthority(value) {
  if (!authorityBrands.has(value)) {
    throw new TypeError('a closed programme status authority is required');
  }
  return value;
}

function snapshotCandidate(candidate) {
  requireExactKeys(candidate, ['envelope', 'validation_input'], 'evidence candidate');
  if (!candidate.envelope || typeof candidate.envelope !== 'object'
    || Array.isArray(candidate.envelope)) {
    throw new TypeError('evidence candidate envelope must be an object');
  }
  if (!candidate.validation_input || typeof candidate.validation_input !== 'object'
    || Array.isArray(candidate.validation_input)) {
    throw new TypeError('evidence candidate validation_input must be an object');
  }
  return {
    envelope: structuredClone(candidate.envelope),
    validation_input: { ...candidate.validation_input },
  };
}

function validatedEvidenceForGate({ authority, gate, evidenceCandidates }) {
  const accepted = [];
  for (const originalCandidate of evidenceCandidates) {
    let candidate;
    try {
      candidate = snapshotCandidate(originalCandidate);
    } catch {
      continue;
    }
    const { envelope } = candidate;
    if (envelope.schema_version !== 'ProgrammeGateEvidenceEnvelope/V2'
      || envelope.gate_id !== gate.id
      || envelope.evidence_contract !== gate.evidence_contract
      || envelope.required_evidence_object_type !== gate.required_evidence_object_type
      || envelope.terminal_state !== 'PASS') {
      continue;
    }

    try {
      const result = authority.validateEvidence({
        ...candidate.validation_input,
        gate,
        envelope,
      });
      if (!result || result.valid !== true || result.gate_id !== gate.id) continue;
      const expectedEnvelopeId = authority.domainDigest(EVIDENCE_ENVELOPE_ID_DOMAIN, envelope);
      const expectedPayloadDigest = authority.domainDigest(
        EVIDENCE_PAYLOAD_DOMAIN,
        authority.evidencePayloadForDigest(envelope),
      );
      requireDigest(result.evidence_envelope_id, 'validated evidence envelope ID');
      requireDigest(result.evidence_payload_digest, 'validated evidence payload digest');
      if (result.evidence_envelope_id !== expectedEnvelopeId
        || result.evidence_payload_digest !== expectedPayloadDigest) {
        continue;
      }
      accepted.push(Object.freeze({
        evidence_envelope_id: expectedEnvelopeId,
        evidence_payload_digest: expectedPayloadDigest,
      }));
    } catch {
      // Invalid evidence deterministically projects OPEN.
    }
  }
  return accepted.length === 1 ? accepted[0] : null;
}

function resolveWorkClasses({
  authority,
  gateStateById,
  generation,
  predecessorStatusId,
}) {
  const registry = authority.registry;
  const workClasses = registry.work_classes;
  const workClassNames = registry.work_class_ids;
  const workClassNameSet = new Set(workClassNames);
  const resolved = new Map();
  const visiting = new Set();

  function dependenciesPass(name) {
    const definition = workClasses[name];
    if (!definition || !Array.isArray(definition.all_of)) {
      throw new TypeError(`work class ${name} must contain an all_of array`);
    }
    return definition.all_of.every((dependency) => {
      if (gateStateById.has(dependency)) return gateStateById.get(dependency) === 'PASS';
      if (workClassNameSet.has(dependency)) return resolve(dependency) === 'PASS';
      throw new Error(`work class ${name} has unknown dependency ${dependency}`);
    });
  }

  function resolve(name) {
    if (resolved.has(name)) return resolved.get(name);
    if (visiting.has(name)) throw new Error(`work-class dependency cycle at ${name}`);
    visiting.add(name);
    const allOfPasses = dependenciesPass(name);
    let state = allOfPasses ? 'PASS' : 'OPEN';
    if (name === 'gate_status_bootstrap') {
      state = allOfPasses
        && authority.bootstrapState === 'AVAILABLE'
        && generation === 1
        && predecessorStatusId === 'NONE'
        ? 'PASS'
        : 'OPEN';
    }
    if (name === 'programme_complete') {
      state = allOfPasses && authority.terminalPairState === 'VALIDATED' ? 'PASS' : 'OPEN';
    }
    visiting.delete(name);
    resolved.set(name, state);
    return state;
  }

  return workClassNames.map((workClass) => Object.freeze({
    work_class: workClass,
    state: resolve(workClass),
  }));
}

function projectProgrammeStatus(input) {
  requireExactKeys(input, [
    'authority',
    'evidenceCandidates',
    'generation',
    'predecessorStatusId',
  ], 'status projection input');
  const authority = requireProgrammeStatusAuthority(input.authority);
  if (!Array.isArray(input.evidenceCandidates)) {
    throw new TypeError('evidenceCandidates must be an array');
  }
  if (!Number.isInteger(input.generation) || input.generation < 1) {
    throw new TypeError('generation must be a positive integer');
  }
  if (input.generation === 1 && input.predecessorStatusId !== 'NONE') {
    throw new Error('generation 1 predecessor must be NONE');
  }
  if (input.generation > 1) {
    requireDigest(input.predecessorStatusId, 'predecessor status ID');
  }

  const supported = new Set(authority.registry.supported_gate_ids);
  const orderedGateProjection = authority.registry.gates.map((gate) => {
    const validated = supported.has(gate.id)
      ? validatedEvidenceForGate({
        authority,
        gate,
        evidenceCandidates: input.evidenceCandidates,
      })
      : null;
    return Object.freeze({
      gate_id: gate.id,
      state: validated ? 'PASS' : 'OPEN',
      evidence_envelope_id: validated ? validated.evidence_envelope_id : null,
      evidence_payload_digest: validated ? validated.evidence_payload_digest : null,
    });
  });
  const gateStateById = new Map(
    orderedGateProjection.map((entry) => [entry.gate_id, entry.state]),
  );

  return Object.freeze({
    ordered_gate_projection: Object.freeze(orderedGateProjection),
    ordered_work_class_projection: Object.freeze(resolveWorkClasses({
      authority,
      gateStateById,
      generation: input.generation,
      predecessorStatusId: input.predecessorStatusId,
    })),
  });
}

function buildUnsignedProgrammeGateStatus(input) {
  requireExactKeys(input, [
    'authority',
    'evidenceCandidates',
    'specificationRoot',
    'codeCommit',
    'environment',
    'generation',
    'predecessorStatusId',
  ], 'status artefact input');
  const authority = requireProgrammeStatusAuthority(input.authority);
  requireDigest(input.specificationRoot, 'specification root');
  requireCommit(input.codeCommit, 'code commit');
  if (!['STAGING', 'PRODUCTION'].includes(input.environment)) {
    throw new Error('environment must be STAGING or PRODUCTION');
  }

  const projection = projectProgrammeStatus({
    authority,
    evidenceCandidates: input.evidenceCandidates,
    generation: input.generation,
    predecessorStatusId: input.predecessorStatusId,
  });
  return Object.freeze({
    schema_version: 'ProgrammeGateStatusArtefact/V2',
    specification_root: input.specificationRoot,
    code_commit: input.codeCommit,
    environment: input.environment,
    generation: input.generation,
    predecessor_status_id: input.predecessorStatusId,
    gate_registry_digest: authority.registry.digest,
    ...projection,
    validator_executable_digest: authority.validatorExecutableDigest,
    validator_configuration_digest: authority.validatorConfigurationDigest,
    validator_key_id: authority.validatorKeyId,
    signature_algorithm: 'Ed25519',
  });
}

function attachProgrammeGateStatusSignature(input) {
  requireExactKeys(
    input,
    ['authority', 'unsignedStatus', 'signature'],
    'status signature attachment input',
  );
  const authority = requireProgrammeStatusAuthority(input.authority);
